// Üretilen dosya: tool/ozgun/uret.py. Sinema ve TV · Belgesel sinema tarihi, belgesel türleri ve gerçeklik anlatımı (Flaherty, Vertov, cinéma vérité, doğrudan sinema, arşiv ve doğa belgeselciliği) (orta).
const ozCinema17Orta = <(String, String, List<String>, String)>[
  ('Lumière Kardeşler\'in tek planlık kısa filmlerini tanımlamak için kullanılan Fransızca kökenli \'actualité\' kavramı belgesel tarihi açısından neyi ifade eder?', 'Gündelik yaşamdan kesitlerin kurgusuz kaydını', ['Tarihsel savaşların stüdyoda canlandırılmasını', 'fantastik öykülerin hileli kurguyla anlatımını', 'Oyuncularla sahnelenen melodramatik öyküleri'], 'Aktüalite filmleri, kameranın gerçek yaşamı ve gündelik olayları dramatik bir öykü kurmadan doğrudan kaydettiği erken dönem yapımlardır.'),
  ('Thomas Edison\'un Kinetograph kamerasına kıyasla Lumière Kardeşler\'in Cinématographe aygıtının belgeselci dış çekimlere olanak tanıyan en temel teknik üstünlüğü neydi?', 'Hafif, taşınabilir ve elektriksiz çalışabilmesi', ['Renkli film şeridini doğrudan işleyebilmesi', 'Eşzamanlı optik ses kaydı gerçekleştirmesi', 'Saniyede yüz kare yüksek hızda çekim yapması'], 'Edison\'un hantal ve stüdyoya bağımlı kamerasının aksine yaklaşık 5 kilogram ağırlığındaki Cinématographe sokaklara ve uzak ülkelere taşınabilmiştir.'),
  ('Bir sinema tarihçisi Venedik\'te gondol üzerinden hareketli kamera (kaydırma/travelling) tekniğinin ilk örneklerinden birini incelemek istediğinde hangi Lumière operatörünün çekimlerine başvurmalıdır?', 'Alexandre Promio', ['Georges Méliès ve asistanları', 'Edwin S. Porter yapım ekibi', 'Charles Pathé stüdyo kameramanları'], 'Alexandre Promio, 1896\'da Venedik Büyük Kanal\'da hareket halindeki bir gondol üzerine kamerasını yerleştirerek erken dönem kaydırma hareketini uygulamıştır.'),
  ('Robert Flaherty\'nin \'Kuzeyli Nanook\' filminin yapım bütçesini hangi sektörde faaliyet gösteren Fransız şirketi Revillon Frères karşılamıştır?', 'Kürk ticareti', ['Demiryolu taşımacılığı', 'Balina yağı rafinerisi', 'Konserve balık üretimi'], 'Büyük film stüdyoları projeyi reddedince Kuzey Kanada\'da ticaret merkezleri bulunan Fransız kürk şirketi Revillon Frères filme sponsor olmuştur.'),
  ('Robert Flaherty\'nin \'Kuzeyli Nanook\' filminde İnuit ailesinin soğuk barınağının içini çekebilmek için başvurduğu ve belgesel etiği tartışmalarına konu olan yöntem nedir?', 'Yarım kubbeli özel bir iglo inşa ettirmesi', ['Stüdyoda yapay kar ve dekor kurdurması', 'Kızılötesi gece görüşlü lensler kullanması', 'Aileyi ahşap bir ticaret kulübesine taşıması'], 'Dönemin hantal kameraları ve yetersiz ışık duyarlılığı nedeniyle gerçek iglo içi karanlık kaldığından Flaherty bir yarısı açık büyük bir iglo yaptırmıştır.'),
  ('Robert Flaherty\'nin \'Kuzeyli Nanook\'ta o dönem tüfek kullanan İnuitlere geleneksel zıpkınla mors avlatması sinema kuramında hangi kavram çerçevesinde eleştirilir?', 'Kurtarma etnografyası ve romantik yeniden canlandırma', ['Doğrudan sinema ve müdahalesiz gözlem tekniği', 'Sovyet montaj kuramı ve ideolojik ajitasyon', 'Sinema-gerçek ve kışkırtıcı sokak röportajı'], 'Flaherty, modernleşmenin izlerini gizleyerek kültürleri Batı teması öncesindeki saf halleriyle sahnelemiş; bu tutum romantik doğalcılık ve kurtarma etnografyası olarak eleştirilmiştir.'),
  ('Robert Flaherty\'nin 1934 yılında İrlanda\'nın batı kıyısındaki kayalık adalarda yaşayan insanların doğayla çetin mücadelesini anlattığı ünlü belgeseli hangisidir?', 'Aranlı Adam', ['Endüstriyel Britanya', 'Gece Postası', 'Kuzey Denizi Balıkçıları'], 'Man of Aran (Aranlı Adam), Flaherty\'nin insan ile acımasız doğa arasındaki çatışma temasını İrlanda\'nın Aran Adaları\'nda sürdürdüğü başyapıtlarındandır.'),
  ('Dziga Vertov\'un Lenin yönetimindeki Bolşevik Partisi\'nin resmi yayın organı \'Pravda\' gazetesine göndermeyle 1922-1925 yılları arasında yayımladığı 23 sayılık haber filmi dizisinin adı nedir?', 'Kino-Pravda', ['Kino-Nedelya bülteni', 'Sovkino güncesi', 'Proletkult haberleri'], '\'Sinema-Gerçek\' anlamına gelen Kino-Pravda, Vertov\'un kurgu ve tipografi denemeleriyle geliştirdiği avangart haber-belgesel serisidir.'),
  ('Dziga Vertov\'un ortaya attığı \'Kino-Glaz\' (Sinema-Göz) kuramının temel iddiası aşağıdakilerden hangisidir?', 'Kamera merceği insan gözünden daha kusursuz algılar', ['Sinema tiyatro sanatının sadık bir kopyası olmalıdır', 'Belgesel filmler edebi roman uyarlamalarına dayanmalıdır', 'Kamera yalnızca sabit üçayak üzerinden çekim yapmalıdır'], 'Vertov\'a göre mekanik \'Sinema-Göz\', insan gözünün yakalayamadığı hız, açı ve kurgusal ilişkileri çözerek yaşamı olduğu gibi yakalama gücüne sahiptir.'),
  ('Dziga Vertov\'un \'Kameralı Adam\' filminde kurgucu Yelizaveta Svilova\'yı kurgu masasında film şeritlerini kesip birleştirirken göstermesi sinemasal açıdan neyi amaçlar?', 'Filmin üretim sürecini görünür kılarak yanılsamayı kırmayı', ['Kurgucunun dramatik öyküdeki kurgusal başrolünü pekiştirmeyi', 'Seyirciyi geleneksel melodram kalıplarıyla özdeşleştirmeyi', 'Sovyet selüloit fabrikalarının teknik reklamını yapmayı'], 'Vertov, kameramanı çekimde ve kurgucuyu masada göstererek özdüşünümsel (self-reflexive) bir dil kurar; sinemanın emek ürünü bir inşa olduğunu vurgular.'),
  ('Bir yönetmen senaryosuz biçimde sokağa çıkıp gizli ya da hareketli kamerayla insanları habersizce kaydederek \'yaşamı suçüstü yakalama\' ilkesini benimsiyorsa hangi öncünün yöntemini uyguluyordur?', 'Dziga Vertov', ['Robert Flaherty', 'Leni Riefenstahl', 'Humphrey Jennings'], '\'Jizn vrasploh\' (yaşamı hazırlıksız/suçüstü yakalama), Dziga Vertov\'un Kino-Glaz ve Kino-Pravda manifestolarının temel ilkelerinden biridir.'),
  ('John Grierson\'ın bizzat yönettiği tek film olan ve 1929\'da Kuzey Denizi\'ndeki ringa balığı avcılarının zorlu emeğini konu alan sessiz belgeselin adı nedir?', 'Drifters', ['Song of Ceylon', 'Night Mail', 'Coal Face'], 'Grierson daha sonra yapımcı ve kuramcı olarak çalışmış; bizzat yönetmenliğini üstlendiği tek film 1929 yapımı \'Drifters\' (Sürüklenenler / Balıkçılar) olmuştur.'),
  ('John Grierson\'ın 1929\'daki Londra prömiyerinde kendi filmi \'Drifters\' ile aynı programda gösterilmesini sağladığı ünlü Sovyet filmi hangisidir?', 'Potemkin Zırhlısı', ['Kameralı Adam', 'Ana ve Oğul', 'Toprak ve Özgürlük'], 'İngiltere\'de genel gösterimi sansürlenen Ayzenştayn\'ın Potemkin Zırhlısı, Londra Film Topluluğu özel gösteriminde Grierson\'ın Drifters filmiyle birlikte sunulmuştur.'),
  ('John Grierson liderliğindeki İngiliz Belgesel Film Hareketi\'nin 1930\'larda benimsediği temel toplumsal işlev anlayışı aşağıdakilerden hangisidir?', 'Yurttaşlık bilincini geliştiren kamusal eğitim aracı olması', ['Bireysel bilinçaltını dışavuran sürrealist sanat üretmesi', 'Ticari gişe başarısıyla özel stüdyoları zenginleştirmesi', 'Sömürge halklarının bağımsızlık ayaklanmalarını kışkırtması'], 'Grierson sinemayı eğlence kürsüsü değil, demokratik toplumda yurttaşları bilgilendiren ve toplumsal sorumluluk aşılayan bir eğitim ve kamu hizmeti aracı olarak görmüştür.'),
  ('John Grierson, 1939 yılında hangi ülkenin daveti üzerine Kuzey Amerika\'ya giderek dünyaca ünlü Ulusal Film Kurulu\'nun (NFB / ONF) kurucu başkanı olmuştur?', 'Kanada', ['Avustralya', 'Yeni Zelanda', 'Güney Afrika'], 'Kanada hükümetinin davetiyle hazırladığı rapor doğrultusunda 1939\'da kurulan National Film Board of Canada\'nın (NFB) ilk komiseri John Grierson olmuştur.'),
  ('Joris Ivens\'in 1928\'de Rotterdam\'daki açılır kapanır çelik demiryolu köprüsünün mekanik hareketlerini görsel bir ritimle incelediği avangart kısa belgeseli hangisidir?', 'Köprü', ['Yağmur', 'Yeni Toprak', 'Borinage'], 'De Brug (Köprü), Joris Ivens\'in mühendislik estetiğini ve kamera açılarını denediği 1928 tarihli biçimci öncü çalışmasıdır.'),
  ('Joris Ivens\'in Mannus Franken ile 1929\'da Amsterdam sokaklarında yaklaşık dört ay boyunca farklı sağanakları çekerek tek bir yağış gibi kurguladığı şiirsel belgesel hangisidir?', 'Yağmur', ['Rüzgârın Öyküsü', 'Seine Nehri', 'Valparaiso'], 'Regen (Yağmur), kent üzerinde başlayan, şiddetlenen ve dinen bir yağmuru lirik ışık ve yansıma oyunlarıyla anlatan şiirsel şehir senfonisi örneğidir.'),
  ('Joris Ivens\'in 1937\'de İspanya İç Savaşı sırasında Cumhuriyetçilerin mücadelesini dünyaya duyurmak için çektiği ve ses bandı metnini Ernest Hemingway\'in seslendirdiği belgesel hangisidir?', 'İspanya Toprağı', ['Endonezya Çağırıyor', 'On Yedinci Paralel', 'Kahramanlık Türküsü'], 'The Spanish Earth (İspanya Toprağı), hem cephe hattını hem de köylülerin toprak sulama çabasını işler; İngilizce anlatımını Ernest Hemingway yazıp seslendirmiştir.'),
  ('Leni Riefenstahl\'ın yönetmenliğini üstlendiği ilk kurmaca film olan ve 1932\'de Venedik Film Festivali\'nde gümüş madalya kazanan mistik dağ draması hangisidir?', 'Mavi Işık', ['Kutsal Dağ', 'Beyaz Cehennem', 'Fırtınalar Üzerinde'], 'Das blaue Licht (Mavi Işık), Riefenstahl\'ın hem başrolünü oynadığı hem yapımcılığını hem de yönetmenliğini üstlendiği 1932 tarihli ilk filmidir.'),
  ('Leni Riefenstahl\'ın 1936 Berlin Yaz Olimpiyatları\'nı konu alan ve \'Ulusların Bayramı\' ile \'Güzelliğin Bayramı\' adlı iki bölümden oluşan belgeselinin genel adı nedir?', 'Olympia', ['Zafer Çelengi', 'Stadyum Senfonisi', 'Altın Meşale'], '1938\'de gösterime giren Olympia, antik Yunan heykelleriyle modern atletlerin bedenlerini bağdaştıran proloğu ve spor çekim teknikleriyle tanınır.'),
  ('Leni Riefenstahl\'ın \'İradenin Zaferi\' filminde geleneksel propaganda belgesellerinden farklı olarak başvurduğu biçimsel tercih aşağıdakilerden hangisidir?', 'Dış ses anlatıcı (voice-over) kullanmayıp kitle görüntüsü, müzik ve konuşmalarla etki yaratması', ['Kongre katılımcılarıyla sokakta eleştirel ve doğaçlama röportajlar gerçekleştirmesi', 'Tüm sahneleri tek bir sabit genel plan kamerayla uzaktan tarafsızca kaydetmesi', 'Sovyet haber filmlerindeki gibi ekranı sürekli istatistiksel ara yazılarla bölmesi'], 'Riefenstahl, açıklayıcı bir dış ses yorumcu kullanmamış; müziğin ritmi, alt açı kameralar, devasa simetrik kitleler ve kürsü konuşmalarıyla hipnotik bir atmosfer kurmuştur.'),
  ('Leni Riefenstahl\'ın \'Olympia\' filminde dört altın madalya kazanarak Nazi rejiminin ırkçı üstünlük tezlerini boşa çıkaran ve filmde de geniş yer bulan Amerikalı atlet kimdir?', 'Jesse Owens', ['Jim Thorpe', 'Carl Lewis', 'Rafer Johnson'], 'Siyahi Amerikalı atlet Jesse Owens\'ın 1936 Berlin Olimpiyatları\'ndaki tarihi başarıları, Riefenstahl\'ın Olympia filminde ağır çekim ve yakın planlarla yer almıştır.'),
  ('Osmanlı topraklarında 1899-1913 yılları arasında özellikle Makedonya ve Manastır çevresinde gündelik yaşamı ve Sultan Mehmet Reşat\'ın ziyaretini filme alan Balkan sinemasının öncü kardeşleri kimlerdir?', 'Manaki Kardeşler', ['Cevat Boyer ve ekibi', 'İpekçi Kardeşler', 'Hrisantos Kardeşler'], 'Yanaki ve Milton Manaki kardeşler, Bioscope 300 kameralarıyla Osmanlı\'nın son dönem Balkan coğrafyasındaki en eski belgesel kayıtlarını bırakmışlardır.'),
  ('Suha Arın\'ın 1964 yılında Ankara\'da çektiği ve yayalar ile sürücülerin trafik kurallarıyla imtihanını konu alan ilk belgesel filminin adı nedir?', 'Başkent\'te Trafik', ['Ankara\'nın Taşı Toprağı', 'Asfalt ve İnsanlar', 'Yaya Geçidi Öyküsü'], 'Suha Arın, sinema eğitimine başlamadan önce Milli Eğitim Bakanlığı Öğretici Filmler Merkezi bünyesinde 1964\'te \'Başkent\'te Trafik\' adlı ilk kısa belgeselini çekmiştir.'),
  ('Suha Arın, sinema ve televizyon alanındaki lisans ve yüksek lisans eğitimini hangi ülkedeki Howard ve American üniversitelerinde tamamlamıştır?', 'Amerika Birleşik Devletleri', ['Birleşik Krallık', 'Fransa Cumhuriyeti', 'Federal Almanya'], 'Suha Arın, 1965\'te gittiği ABD\'de Washington D.C.\'deki Howard Üniversitesi\'nde sinema-TV lisansı ve American Üniversitesi\'nde kitle iletişimi yüksek lisansı yapmıştır.'),
  ('Suha Arın\'ın 1979 yılında Toros Dağları\'nda orman işçiliği yapan Alevi-Türkmen topluluğundan 12 yaşındaki bir kız çocuğunun yaşamını ve özlemlerini anlattığı belgesel hangisidir?', 'Tahtacı Fatma', ['Fırat\'ın Türküsü', 'Yörük Elif\'in Düşleri', 'Torosların Çocukları'], 'Tahtacı Fatma, yüksek ormanlarda ağır koşullarda çalışan Tahtacı topluluğunu çocuk emeği ve umutları üzerinden işleyen toplumsal gerçekçi bir başyapıttır.'),
  ('Suha Arın belgeselciliğini kendisinden önceki \'Anadolu uygarlıkları / Hümanist kültür filmleri\' geleneğinden ayıran en belirgin içerik özelliği nedir?', 'Tarihsel ve mimari mirası güncel toplumsal-ekonomik insan sorunlarıyla birlikte ele alması', ['İnsan figürünü tamamen dışlayarak yalnızca müze vitrinlerindeki arkeolojik eserleri çekmesi', 'Doğal mekânları reddedip tarihi olayları kostümlü tiyatro oyuncularıyla stüdyoda canlandırması', 'Anlatıcı ses ve müziği tamamen kaldırarak yalnızca sabit güvenlik kamerası estetiği kullanması'], 'Suha Arın, salt arkeolojik veya turistik tanıtım yapmak yerine mekânı içinde yaşayan insanın emeği, göçü, yoksulluğu ve kültürel değişimiyle bütünleştirmiştir.'),
  ('Türkiye\'de genç belgeselcileri desteklemek ve Suha Arın\'ın mirasını yaşatmak amacıyla her yıl düzenlenen köklü ulusal belgesel film şenliği hangisidir?', 'Altın Safran Belgesel Film Festivali', ['Altın Koza Uzun Metraj Yarışması', 'Uçan Süpürge Kadın Filmleri Festivali', 'Randevu İstanbul Sinema Günleri'], 'Safranbolu\'da Zaman belgeselinin kente katkısına vefa olarak düzenlenen Uluslararası Altın Safran Belgesel Film Festivali bünyesinde Suha Arın adına özel ödüller de verilmektedir.'),
  ('1920\'lerin sonunda Walter Ruttmann\'ın \'Berlin: Büyük Bir Kentin Senfonisi\' ve Dziga Vertov\'un \'Kameralı Adam\' filmleriyle doruğa ulaşan erken dönem belgesel alt türü hangisidir?', 'Şehir Senfonileri', ['Doğrudan Sinema', 'Mondo Belgeselleri', 'Sahte Belgesel'], 'Şehir Senfonileri (City Symphonies), modern metropol yaşamının şafaktan geceye ritmini müzikal kurgu ilkeleriyle aktaran 1920\'ler avangart belgesel akımıdır.'),
  ('Bir sinema öğrencisi ödevinde gerçek olayları, yerleri ve sıradan insanları kullanmakla birlikte bu malzemeyi şiirsel bir kurgu, ritim ve ses tasarımıyla yeniden biçimlendiriyorsa kimin belgesel tanımını doğrudan hayata geçiriyordur?', 'John Grierson', ['Auguste Lumière', 'Thomas Edison', 'Georges Méliès'], 'John Grierson\'ın \'gerçekliğin yaratıcı biçimde işlenmesi\' ilkesi, ham gerçeklik kaydının sanatsal ve dramatik bir kurguyla anlamlandırılmasını savunur.'),
  ('Lumière Kardeşler\'in \'Sulanan Bahçıvan\' (L\'Arroseur Arrosé) filmi, aynı yıl çekilen \'Fabrikadan Çıkan İşçiler\' filminden hangi yönüyle ayrılarak sinema tarihinde farklı bir kolu başlatmıştır?', 'Sahnelenmiş komik bir kurmaca öykü içermesiyle', ['Tamamen gizli kamerayla habersiz çekilmesiyle', 'Doğal ses kaydıyla senkronize gösterilmesiyle', 'Savaş cephesindeki gerçek çatışmaları belgelemesiyle'], 'Fabrikadan Çıkan İşçiler belgesel/aktüalite kolunu başlatırken, hortuma basıp bahçıvanı ıslatan çocuğun öyküsü olan Sulanan Bahçıvan kurmaca komedi sinemasının ilk örneği sayılır.'),
  ('1930\'larda ABD\'de Büyük Buhran ve kuraklık felaketini konu alan \'The Plow That Broke the Plains\' ve \'The River\' adlı kamu destekli klasik belgesellerin yönetmeni kimdir?', 'Pare Lorentz', ['Robert Flaherty', 'Frank Capra', 'Willard Van Dyke'], 'Roosevelt\'in New Deal (Yeni Düzen) politikaları kapsamında kurulan ABD Film Servisi\'nin öncüsü Pare Lorentz, çevre yıkımı ve tarım politikaları üzerine lirik sosyal belgeseller üretmiştir.'),
  ('Belgesel sinema tarihinde Lumière Kardeşler, Robert Flaherty, Dziga Vertov ve John Grierson\'ın katkıları birlikte değerlendirildiğinde aşağıdakilerden hangisi söylenebilir?', 'Lumière gerçekliği kaydetmiş, Flaherty öyküleştirmiş, Vertov avangart kurguyla çözümlemiş, Grierson toplumsal-kurumsal kimliğe kavuşturmuştur', ['Dört öncü de belgesel sinemada müziğin, kurgunun ve yakın plan çekimlerin tamamen yasaklanması gerektiği konusunda uzlaşmıştır', 'Flaherty ve Grierson gizli sokak kamerasını savunurken, Lumière ve Vertov stüdyoda kostümlü yeniden canlandırmayı zorunlu görmüştür', 'Belgesel sinema terimini ilk kez Lumière Kardeşler tanımlamış, son şeklini ise sessiz dönemde Leni Riefenstahl vermiştir'], 'Erken dönem belgesel tarihi; Lumière\'in ham kaydı, Flaherty\'nin insan-doğa öykücülüğü, Vertov\'un Sinema-Göz kurgusu ve Grierson\'ın kuramsal/kurumsal inşasıyla şekillenmiştir.'),
  ('Robert Flaherty\'nin \'Kuzeyli Nanook\'tan önce 1913-1916 yılları arasında Kuzey Kanada\'da çektiği yaklaşık 9 bin metrelik ilk belgesel materyalinin başına Toronto\'da ne gelmiştir?', 'Kurgu odasında Flaherty\'nin sigarasından çıkan yangında yanıp kül olmuştur', ['Kanada hükümeti tarafından askeri sır gerekçesiyle el konulup imha edilmiştir', 'Atlantik Okyanusu\'nu geçen posta gemisinin batması sonucu sulara gömülmüştür', 'Soğuk hava deposunda yanlış kimyasalla yıkandığı için tamamen kararmıştır'], 'Nitrat tabanlı yanıcı film şeritleri Flaherty\'nin düşürdüğü sigara izmaritiyle alev almış; bu felaket Flaherty\'yi tek bir ailenin öyküsüne odaklanacağı yeni bir çekime yöneltmiştir.'),
  ('Antropolojik bir belgesel çekmek isteyen yönetmen, çekim yapacağı köyde kamerayı çalıştırmadan önce aylarca yaşayıp öyküyü dışarıdan dayatmak yerine içeriden keşfetmeyi seçiyorsa kimin çalışma ilkesini izliyordur?', 'Robert Flaherty', ['Leni Riefenstahl', 'Dziga Vertov', 'Esfir Şub'], 'Flaherty\'nin en önemli mirası, önceden yazılmış katı senaryolar yerine çekilecek toplulukla uzun süre yaşayarak öyküyü onların doğal yaşam döngüsünden çıkarma yöntemidir.'),
  ('Dziga Vertov\'un 1924 yılında tamamladığı ve Sovyet yaşamını geriye sarma (reverse motion) gibi kamera hileleriyle çözümleyerek Venedik veya Paris sergilerinde ödül kazanan uzun metrajlı belgeseli hangisidir?', 'Kinoglaz', ['Kino-Pravda No: 1', 'Adım Adım Sovyet', 'Geleceğin İnsanları'], 'Kinoglaz (Sinema-Göz: Olağanüstü Yaşam), ekmeğin fırından tarlaya ve kesilmiş öküzün canlanıp çayıra dönüşünü geriye sararak üretim ilişkilerini öğreten öncü bir yapıttır.'),
  ('Dziga Vertov\'un kurgu kuramında iki görüntü arasındaki hareket, hız, ışık ve yön ilişkilerine dayalı geçişleri açıklamak için kullandığı temel kavram nedir?', 'Aralıklar Kuramı', ['Zihinsel Çekim', 'Biyomekanik Oyunculuk', 'Kuleşov Coğrafyası'], 'Vertov\'un \'Aralıklar Kuramı\' (Theory of Intervals), müzikal notalar arasındaki ilişkiye benzer biçimde filmin anlamının tekil karelerden değil iki çekim arasındaki görsel-hareketsel farktan doğduğunu savunur.'),
  ('Dziga Vertov\'un \'Kameralı Adam\' filminde Moskova sokaklarında hızla giden bir at arabasının görüntüsünü aniden dondurup (freeze-frame) ardından sinema perdesine ve kurgu odasına kesme yapması neyi gösterir?', 'Zaman ve hareketin kamera ile kurgu tarafından denetlenebilen sinemasal malzemeler olduğunu', ['Çekim sırasında kameranın yay mekanizmasının bozulup filmin koptuğunu', 'Sovyet kent içi ulaşımında at arabalarının yasaklanıp tramvaya geçildiğini', 'Fotoğraf sanatının hareketli sinemadan daha üstün bir gerçeklik sunduğunu'], 'Hareketsiz karelerin kurgu şeridinde tek tek gösterilmesi ve yeniden canlandırılması, sinemanın durağan fotoğraflardan hareket yaratan maddi doğasını izleyiciye açıklar.'),
  ('John Grierson yönetimindeki GPO Film Birimi\'nde hem ses deneyleri hem de gerçekçi dramatik anlatım konusunda kilit rol oynayan Brezilya asıllı avangart yönetmen ve yapımcı kimdir?', 'Alberto Cavalcanti', ['Jean Painlevé', 'Luis Buñuel', 'Joris Ivens'], 'Fransa\'da \'Rien que les heures\' şehir senfonisini çektikten sonra 1934\'te GPO\'ya katılan Alberto Cavalcanti, İngiliz belgesel okulunun ses ve anlatı kalitesini büyük ölçüde yükseltmiştir.'),
  ('John Grierson\'ın \'İlk İlkeler\' (First Principles of Documentary) başlıklı kuramsal yazısında stüdyo kurmacasına karşı savunduğu temel görüş hangisidir?', 'Gerçek mekânın ve gerçek insanın sahnelenmiş öykü ve profesyonel oyuncudan daha derin bir hakikat taşıdığı', ['Belgesel filmlerde kurgu makasının hiç kullanılmaması ve tek plan çekilmesi gerektiği', 'Kameranın yalnızca doğa manzaralarını çekip kent ve sanayi bölgelerinden uzak durması', 'Kamu kurumlarının sinema üretimine hiçbir şekilde maddi destek sağlamaması gerektiği'], 'Grierson\'a göre yaşayan sahne ve gerçek insan davranışı, stüdyo dekoru ve aktör taklidinin ulaşamayacağı zenginlikte dramatik olanaklar barındırır.'),
  ('Joris Ivens\'in Hollanda\'da Sergey Ayzenştayn, Dziga Vertov ve Pudovkin gibi yasaklı ya da az bilinen avangart yönetmenlerin filmlerini göstermek üzere 1927\'de kurucuları arasında yer aldığı sinema kulübü hangisidir?', 'Filmliga', ['Ciné-Liberté', 'Kino-Göz Derneği', 'Amsterdamer Kamera'], 'Amsterdam merkezli Nederlandsche Filmliga, ticari sinemaya ve sansüre karşı avangart ve Sovyet sinemasını savunan öncü bir Avrupa film topluluğudur.'),
  ('Joris Ivens\'in 1945\'te Avustralya liman işçilerinin Hollanda sömürge gemilerine silah yüklemeyi reddetmesini desteklediği için kendi ülkesi Hollanda ile yıllarca süren gerilim yaşamasına yol açan belgesel hangisidir?', 'Indonesia Calling', ['Özgür Cava', 'Pasifik Dalgaları', 'Sömürge Sonu'], 'Avustralya Film Kurulu komiserliği görevinden istifa ederek çektiği Indonesia Calling (Endonezya Çağırıyor, 1946) nedeniyle Hollanda hükümeti yıllarca Ivens\'in pasaportuna kısıtlama getirmiştir.'),
  ('Bir belgeselci hem biçimsel kamera estetiğine ve şiirselliğe büyük özen gösteriyor hem de kamerasını grevdeki işçilerin ve bağımsızlık savaşı veren halkların dayanışma aracı olarak konumlandırıyorsa hangi öncünün çizgisine en yakındır?', 'Joris Ivens', ['Leni Riefenstahl', 'Auguste Lumière', 'F. W. Murnau'], 'Joris Ivens, avangart şiirsellik (Yağmur, Rüzgârın Öyküsü) ile militan enternasyonalist dayanışmayı (Borinage, İspanya Toprağı, 17. Paralel) birleştiren eşsiz bir ustadır.'),
  ('Leni Riefenstahl\'ın \'İradenin Zaferi\'nden bir yıl önce, 1933\'teki Nürnberg Parti Kongresi üzerine çektiği ve daha sonra dağıtımı durdurulan ilk propaganda belgeselinin adı nedir?', 'İnancın Zaferi', ['Alman Şafağı', 'Nürnberg Günleri', 'Bayraklar Altında'], 'Der Sieg des Glaubens (İnancın Zaferi, 1933), SA lideri Ernst Röhm\'e geniş yer verdiği için 1934\'teki Uzun Bıçaklar Gecesi tasfiyesinin ardından rejim tarafından ortadan kaldırılmıştır.'),
  ('\'İradenin Zaferi\' belgeseli sinema etiği ve kuramı tartışmalarında neden salt \'tarafsız bir gözlem kaydı\' olarak kabul edilmez?', 'Kongre mekânı, geçit törenleri ve ışıklandırmanın doğrudan kameraların çekim açılarına göre sahnelenmiş olması nedeniyle', ['Tüm sahnelerin kongreden yıllar sonra Berlin dışındaki film stüdyolarında figüranlarla çekilmesi nedeniyle', 'Görüntülerin tamamının yabancı haber ajanslarından izinsiz alınıp montajlanması nedeniyle', 'Filmin hiçbir gerçek konuşma veya ses kaydı içermeyen çizgi animasyonlardan oluşması nedeniyle'], 'Nürnberg Kongresi, Albert Speer\'in mimari düzenlemesi ve Riefenstahl\'ın 30\'dan fazla kamerası için adeta dev bir film seti olarak tasarlanmış; gerçeklik kamera için sahnelenmiştir.'),
  ('Osmanlı İmparatorluğu\'nda 1915 yılında Enver Paşa\'nın talimatıyla kurulan ve bir devlet kurumu olarak savaş cephelerinden aktüalite ile belgeseller üreten ilk resmi sinema örgütü hangisidir?', 'Merkez Ordu Sinema Dairesi', ['Darülbedayi Sinema Şubesi', 'Milli Sinema Cemiyeti', 'Şark Film Kumpanyası'], 'Kısaca MOSD olarak bilinen Merkez Ordu Sinema Dairesi, Alman askeri sinema birimleri örnek alınarak kurulmuş ve Türkiye\'de kurumsal belgesel-haber filmciliğinin temelini atmıştır.'),
  ('1950\'li yıllarda İstanbul Üniversitesi Edebiyat Fakültesi bünyesinde kurulan ve Anadolu uygarlıklarını konu alan sanat-kültür belgeselleriyle \'Kültür Filmleri\' ekolünü başlatan merkez hangisidir?', 'İstanbul Üniversitesi Film Merkezi', ['Devlet Güzel Sanatlar Sinema Kulübü', 'Ankara Radyosu Görsel Arşivi', 'Yeşilçam Belgesel Yapımcılar Birliği'], 'Sabahattin Eyüboğlu, Mazhar Şevket İpşiroğlu ve Aziz Albek\'in öncülük ettiği İÜ Film Merkezi; Hitit Güneşi, Siyah Kalem, Surnâme ve Anadolu Yolları gibi klasikleri üretmiştir.'),
  ('Suha Arın\'ın kurduğu ve Türkiye\'de pek çok genç sinemacı için bir okul işlevi gören bağımsız film yapım şirketinin adı nedir?', 'MTV Film', ['Arın Görsel Sanatlar', 'Safran Filmcilik', 'Toros Belgesel Evi'], 'Suha Arın\'ın 1976\'da kurduğu MTV (Merkez Televizyon ve Filmcilik), belgesel yapımcılığında usta-çırak geleneğinin sürdüğü önemli bir üretim merkezi olmuştur.'),
  ('Suha Arın\'ın büyük usta Mimar Sinan\'ın yaşamını ve başyapıtlarını kendi ağzından anımsamalar biçiminde kurguladığı 1988 tarihli belgeseli hangisidir?', 'Mimar Sinan\'ın Anıları', ['Taşa Yazılan Destan', 'Kubbelerin Efendisi', 'Süleymaniye\'nin Sırrı'], 'Tezkiretü\'l-Bünyan gibi tarihsel kaynaklardan yararlanan \'Mimar Sinan\'ın Anıları\', büyük mimarın estetik ve mühendislik dehasını görsel bir şiirsellikle aktarır.'),
  ('Suha Arın\'ın \'Tahtacı Fatma\' belgeselinde 12 yaşındaki Fatma\'nın ormanda ağır tomruk işlerinde çalışırken kurduğu en belirgin gelecek düşü izleyiciye hangi toplumsal mesajı verir?', 'Kırsal çocuk işçiliğinin eğitim hakkı ve fırsat eşitsizliğiyle kurduğu acı çelişkiyi', ['Orman köylülerinin geleneksel göçebe yaşamdan tamamen memnun olduklarını', 'Ağaç kesim makinelerinin Toros ormanlarında insan gücünü gereksiz kıldığını', 'Çocukların sinema oyuncusu olmak için köylerinden büyük kentlere kaçtığını'], 'Fatma\'nın okula gidip hemşire ya da kentte daha rahat bir yaşam sürme özlemi ile elindeki balta ve hızar gerçeği arasındaki karşıtlık, filmin dramatik omurgasını oluşturur.'),
  ('Mimari koruma konulu bir belgesel hazırlayan yönetmen, yalnızca konakların tavan işlemelerini göstermekle yetinmeyip o evlerde yaşayan yaşlıların yalnızlığını ve ekonomik değişimi de öyküye katıyorsa Türkiye\'de hangi belgeselcinin yaklaşımını sürdürüyordur?', 'Suha Arın', ['Fuat Uzkınay', 'Cemil Filmer', 'Turgut Özakman'], 'Suha Arın \'Safranbolu\'da Zaman\' ve \'Eski Evler Eski Ustalar\'da mimariyi cansız bir taş-ahşap yığını olarak değil, içindeki insanın zamanla değişen sosyokültürel öyküsüyle birlikte ele almıştır.'),
  ('Bill Nichols\'ın belgesel sınıflandırmasında Dziga Vertov\'un \'Kameralı Adam\' filmi, kameramanı ve kurgu sürecini bizzat filmin içine yerleştirdiği için hangi kipin en erken başyapıtı sayılır?', 'Düşünümsel (Reflexive) kip', ['Gözlemsel (Observational) kip', 'Açıklayıcı (Expository) kip', 'Kurmaca-Belgesel kip'], 'Düşünümsel kip, belgeselin nasıl temsil edildiğini ve üretildiğini izleyiciye sorgulatır; Vertov\'un Kameralı Adam\'ı bu yaklaşımın sinema tarihindeki en parlak öncüsüdür.'),
  ('1921 yılında New York avangart sanatçıları Charles Sheeler ve Paul Strand tarafından çekilen ve Walt Whitman\'ın dizelerinden esinlenerek \'Şehir Senfonisi\' türünün ilk habercisi sayılan kısa film hangisidir?', 'Manhatta', ['Rien que les heures', 'À propos de Nice', 'Regen'], 'Ressam Sheeler ve fotoğrafçı Strand\'in gökdelenleri, limanı ve dumanlarıyla New York\'u soyut geometrik açılarla görüntülediği \'Manhatta\' (1921), şehir senfonilerinin öncüsüdür.'),
  ('1932 yılında İspanyol sürrealist yönetmen Luis Buñuel\'in İspanya\'nın en yoksul ve unutulmuş dağlık bölgesindeki sefaleti sarsıcı ve ironik bir dış sesle belgelediği filmi hangisidir?', 'Ekmeksiz Toprak', ['Endülüs Köpeği', 'Altın Çağ', 'Unutulmuşlar'], 'Las Hurdes: Tierra sin pan (Ekmeksiz Toprak), geleneksel gezi ve etnografya filmlerinin huzurlu tonunu tersyüz eden sert ve rahatsız edici bir toplumsal belgeseldir.'),
  ('1920\'ler ve 1930\'larda belgesel sinemacıların 35 mm kameralar yanında yeni geliştirilen taşınabilir yaylı el kameralarını (örneğin Kinamo veya Eyemo) kullanmaya başlaması hangi estetik değişimi sağlamıştır?', 'Üçayaktan (tripod) kurtulan kameranın sokakta, kalabalıkta ve dar alanlarda özgürce hareket edebilmesini', ['Filmlerin banyo edilmeden doğrudan televizyon ekranlarına canlı yayınla aktarılmasını', 'Gece zifiri karanlıkta hiçbir ışık kaynağı olmadan renkli çekim yapılabilmesini', 'Tek bir film kasetiyle yirmi dört saat kesintisiz sesli kayıt alınabilmesini'], 'Joris Ivens\'in elinden düşürmediği küçük Kinamo ve Vertov ekibinin kullandığı taşınabilir kameralar, sinemacıyı hantal üçayak bağımlılığından kurtarıp yaşamın içine sokmuştur.'),
  ('1930\'larda optik ses kayıt donanımlarının kamyonlarla taşınacak kadar ağır olması belgesel sinemanın biçimini nasıl etkilemiştir?', 'Sahada doğaçlama diyalog yerine stüdyoda yazılmış yorumcu metin ve bestelenmiş müziğin egemen olmasına yol açmıştır', ['Tüm belgesel yönetmenlerinin mesleği bırakıp radyo tiyatrosu yazarlığına geçmesine neden olmuştur', 'Belgesel filmlerin yalnızca sessiz pandomim sanatçılarıyla tiyatro sahnelerinde çekilmesini zorunlu kılmıştır', 'Kamera hareketlerinin tamamen ortadan kalkıp yalnızca sabit fotoğrafların gösterilmesine sebep olmuştur'], 'Taşınabilir senkronize ses cihazları (Nagra vb.) 1960\'lara dek gelişmediği için 1930-1950 arası klasik belgesellerde kurgu ve stüdyo dış sesi belirleyici olmuştur.'),
  ('Bir sinema tarihçisi erken dönem belgesellerde \'şiirsel montaj ile endüstriyel modernleşme propagandası\' arasındaki bağı karşılaştırmalı olarak incelemek istediğinde aşağıdaki eşleştirmelerden hangisini seçmesi en uygundur?', 'Dziga Vertov\'un \'Coşku: Donbas Senfonisi\' ve Viktor Turin\'in \'Turksib\' filmlerini', ['Lumière Kardeşler\'in \'Bebeğin Kahvaltısı\' ve \'Sulanan Bahçıvan\' filmlerini', 'Robert Flaherty\'nin \'Moana\' ve F. W. Murnau\'nun \'Tabu\' filmlerini', 'Suha Arın\'ın \'Safranbolu\'da Zaman\' ve \'Eski Evler Eski Ustalar\' filmlerini'], 'Hem Donbas Senfonisi hem de Turksib, Sovyet sanayileşme ve altyapı hamlesini biçimsel montaj ritmiyle işleyen öncü yapımlardır.'),
  ('Joris Ivens\'in \'Yağmur\' (1929) ve Dziga Vertov\'un \'Kameralı Adam\' (1929) filmleri kronolojik bir gerçekliği izliyormuş gibi görünmelerine rağmen gerçekte nasıl üretilmişlerdir?', 'Aylar süren çekimlerde farklı gün ve yerlerde kaydedilen yüzlerce planın kurgu masasında tek bir gün veya tek bir yağmur gibi birleştirilmesiyle', ['Sabah saat sekizden akşam altıya kadar hiçbir kesme yapılmadan tek bir kameranın kesintisiz çalıştırılmasıyla', 'Tüm sahnelerin kapalı film platolarında yapay yağmur makineleri ve maket binalar kullanılarak çekilmesiyle', 'Yalnızca amatör turistlerin gönderdiği tatil fotoğraflarının peş peşe dizilerek hareketlendirilmesiyle'], 'Her iki başyapıt da \'yaratıcı coğrafya ve zaman\' kurgusunun örneğidir; Ivens dört aylık yağmurları tek sağanak, Vertov dört farklı kenti tek bir Sovyet kenti ve tek bir gün olarak kurgulamıştır.'),
  ('John Grierson\'ın 1926\'daki yazısından önce Fransız sinema yazarlarının \'documentaire\' sözcüğünü hangi tür filmleri tanımlamak için kullandığı bilinmektedir?', 'Uzak diyarları tanıtan ciddi gezi ve keşif filmleri', ['Polisiye mahkeme tutanaklarına dayanan cinayet dramaları', 'Sessiz dönem komedi yıldızlarının kamera arkası görüntüleri', 'Ordu birliklerinin kapalı devre askeri eğitim kayıtları'], 'Fransızcada 1910\'lar ve 1920\'lerin başında \'documentaire\', egzotik coğrafyaları ve bilimsel seferleri konu alan gezi filmlerini (travelogue) kurmacadan ayırmak için kullanılıyordu.'),
  ('Dziga Vertov\'un \'Kameralı Adam\' filminin başında kameramanın dev bir kameranın tepesine çıkması ve salon koltuklarının kendiliğinden açılıp orkestranın hazırlanması neyi simgeler?', 'Geleneksel tiyatro-edebiyat kalıplarından arınmış özerk bir sinema deneyiminin başladığını', ['Moskova Büyük Tiyatrosu\'nda yeni bir klasik bale eserinin sahneleneceğini', 'Sinema salonlarındaki koltuk mekanizmalarının otomatik yay sisteminin tanıtımını', 'Yönetmenin seyircileri uyutarak hipnoz altına almak istediğini'], 'Filmin açılışındaki sinema salonu sekansı, izleyicinin pasif bir kurmaca tüketicisi değil, kendi üretim araçlarının bilincinde olan yeni bir görsel dilin tanığı olacağını ilan eder.'),
  ('Suha Arın\'ın \'Safranbolu\'da Zaman\' (1976) belgeseli toplumsal etki açısından değerlendirildiğinde belgesel sinemanın hangi gücünü somut biçimde kanıtlamıştır?', 'Bir belgesel filmin kamuoyu ve yerel yönetimlerde koruma bilinci yaratarak kentsel-kültürel mirası yıkımdan kurtarabileceğini', ['Belgesel filmlerin ticari sinema salonlarında Amerikan aksiyon filmlerinden daha yüksek gişe geliri elde edebileceğini', 'Tarihi kasabaların tamamının boşaltılıp yalnızca sinema stüdyosu olarak kullanılması gerektiğini', 'Mimari yapıların korunması için ahşap konakların yıkılıp yerine betonarme kopyalarının yapılmasının yeterli olduğunu'], 'Safranbolu\'da Zaman gösterildikten sonra kent Türkiye\'de koruma mimarisinin simgesi haline gelmiş, sit alanı kararları güçlenmiş ve Safranbolu 1994\'te UNESCO Dünya Mirası Listesi\'ne girmiştir.'),
  ('Fransız Cinéma Vérité ile Amerikan Doğrudan Sinema akımları arasındaki en temel epistemolojik ve yöntemsel fark aşağıdakilerden hangisidir?', 'Cinéma Vérité kamerayı gerçeği açığa çıkaran bir kışkırtıcı olarak kullanırken Doğrudan Sinema müdahalesiz gözlemi savunur', ['Cinéma Vérité yalnızca stüdyo dekorlarında çalışırken Doğrudan Sinema sadece gizli güvenlik kameraları kullanır', 'Cinéma Vérité ses kaydını tamamen reddederken Doğrudan Sinema tüm filmlerini senfonik orkestra müziğiyle kurgular', 'Cinéma Vérité yalnız doğa ve yaban hayatı çekerken Doğrudan Sinema sadece tarihsel canlandırmalara yer verir'], 'Rouch\'un Cinéma Vérité anlayışında kamera varlığıyla yeni bir gerçeklik kışkırtır; Amerikalı Doğrudan Sinemacılar ise olayların kameradan bağımsız akışını izlemeyi hedefler.'),
  ('Bill Nichols\'ın belgesel kipleri tarihsel gelişim sırasıyla düşünüldüğünde yeni bir kipin ortaya çıkışı çoğunlukla hangi dinamikle açıklanır?', 'Önceki baskın kipin gerçekliği temsil etmedeki sınırlılıklarına ve ahlaki-estetik uzlaşımlarına duyulan tepkiyle', ['Devlet sansür kurullarının her on yılda bir eski çekim tekniklerini resmen yasaklamasıyla', 'Sinema salonlarındaki projeksiyon cihazlarının siyah-beyaz filmleri gösteremez hale gelmesiyle', 'Belgesel yönetmenlerinin kurmaca sinema endüstrisinden tamamen kopup televizyon haberciliğine geçmesiyle'], 'Nichols\'a göre her yeni kip, bir önceki kipin "gerçeklik" iddiasındaki kör noktaları aşmak isteyen sinemacıların biçimsel arayışlarından doğar; ancak eski kipler yok olmaz.'),
  ('1960\'larda geliştirilen "kristal senkron" (crystal sync) teknolojisi kamera ile ses kayıt cihazı arasındaki uyumu nasıl sağlamıştır?', 'Kamera motoru ile teybin hızını kuvars kristaliyle sabitleyerek aradaki fiziksel bağlantı kablosunu gereksiz kılmıştır', ['Görüntü ve sesi aynı 8 mm manyetik şerit üzerine uydu sinyalleri aracılığıyla anlık olarak basmıştır', 'Ses dalgalarını çekim sırasında otomatik olarak altyazıya dönüştürüp film negatifinin kenarına işlemiştir', 'Mikrofonları kameranın objektif kapağına yerleştirerek yalnızca kameraya bakan kişilerin sesini kaydetmiştir'], 'Kuvars kristalli hız kontrolü sayesinde kamera ve Nagra teyp birbirine kabloyla bağlanmadan aynı sabit hızda çalışabilmiş, böylece görüntü ve ses kurguda tam eşleşmiştir.'),
  ('Bir yönetmen, göçmen işçilerle yaptığı röportajların ortasında kurguyu durdurup kendi sorusunun yönlendiriciliğini tartışmaya açıyor ve ışık ekibini kadraja dahil ediyorsa hangi kipi kullanmaktadır?', 'Düşünümsel kip', ['Gözlemci kip', 'Açıklayıcı kip', 'Şiirsel kip'], 'Yönetmenin kendi temsil yöntemini, soru sorma biçimini ve çekim mekanizmasını film içinde sorgulaması düşünümsel kipin ayırt edici özelliğidir.'),
  ('Hiçbir röportaj, altyazı bilgisi veya dış ses kullanmadan bir acil servisin yirmi dört saatlik mesaisini uzun planlarla takip eden bir belgesel hangi kipe örnektir?', 'Gözlemci kip', ['Açıklayıcı kip', 'Katılımcı kip', 'Edimsel kip'], 'Müzik, dış ses, ara yazı ve röportajdan kaçınarak kurum içi gündelik pratikleri gerçek zaman hissiyle aktarmak gözlemci kipin temel yaklaşımıdır.'),
  ('Kuir kimliğini ve ailesiyle yaşadığı kırılmaları şiirsel günlük kayıtları, sahnelenmiş anılar ve yoğun kişisel dışavurumlarla anlatan bir yönetmen ağırlıklı olarak hangi kipe yaklaşır?', 'Edimsel kip', ['Açıklayıcı kip', 'Gözlemci kip', 'Katılımcı kip'], 'Kimlik politikaları, kişisel hafıza, duygusal yoğunluk ve öznel deneyimin sahnelenmesi 1980\'lerden itibaren öne çıkan edimsel kipin merkezindedir.'),
  ('Arşiv görüntüleri üzerine kendinden emin bir spiker sesi yerleştirerek küresel ısınmanın nedenlerini madde madde kanıtlamaya çalışan televizyon belgeseli hangi kipte üretilmiştir?', 'Açıklayıcı kip', ['Düşünümsel kip', 'Gözlemci kip', 'Şiirsel kip'], 'Sorun-çözüm mantığı kuran, görüntüleri sözlü metnin kanıtı olarak kullanan ve otoriter dış sese dayanan yapımlar açıklayıcı kipin tipik örnekleridir.'),
  ('Bir sinemacı, yıllar önce kapandığı söylenen bir maden kasabasına gidip eski işçilerle kamera önünde yüzleşiyor ve arşiv belgelerini onlara gösterip tepkilerini kaydediyorsa hangi kip baskındır?', 'Katılımcı kip', ['Şiirsel kip', 'Gözlemci kip', 'Açıklayıcı kip'], 'Yönetmenin sahada bizzat bulunup öznelerle etkileşim kurması, tanıklıkları görüşmeler ve yüzleşmeler yoluyla üretmesi katılımcı kipi tanımlar.'),
  ('Sanayi tesislerindeki çarkların dönüşünü, buhar bulutlarını ve yağmur damlalarını hiçbir bilgilendirici metin olmadan müzikal bir kurgu ritmiyle birleştiren kısa belgesel hangi kipe girer?', 'Şiirsel kip', ['Katılımcı kip', 'Açıklayıcı kip', 'Düşünümsel kip'], 'Nesneleri tarihsel bağlamlarından soyutlayarak görsel biçim, hareket uyumu ve ritmik montaj etrafında örmek şiirsel kipin temel stratejisidir.'),
  ('Açıklayıcı kipte sıkça başvurulan "kanıtlama amaçlı kurgu" (evidentiary editing) klasik kurmaca sinemadaki süreklilik kurgusundan hangi yönüyle ayrılır?', 'Mekânsal ve zamansal sürekliliği korumak yerine farklı zaman ve yerlerden görüntüleri tek bir sözlü tezi desteklemek için birleştirir', ['Kameranın 180 derece aks çizgisini aşmasını engellemek için yalnızca tek bir sabit açıdan çekilmiş planları kullanır', 'İzleyicinin duygusal özdeşleşmesini artırmak amacıyla sadece başkarakterin bakış açısı planlarına yer verir', 'Kurgu kesmelerini tamamen gizlemek için bütün filmi tek bir kesintisiz plan-sekans olarak tasarlar'], 'Kanıtlama amaçlı kurguda farklı mekân ve zamanlara ait planlar, dış sesin yürüttüğü mantıksal argümanı bütünlemek amacıyla yan yana getirilir.'),
  ('Robert Drew ve ekibinin Time Inc. bünyesinde geliştirdiği "kriz yapısı" (crisis structure) Doğrudan Sinema filmlerinde hangi anlatı sorununu çözmek için kullanılmıştır?', 'Dış ses ve röportaj kullanılmadığında dağılabilecek gözlemsel malzemeye doğal bir dramatik gerilim ve bütünlük kazandırmak', ['Yönetmenin kamera önünde yaptığı politik konuşmaların izleyici tarafından sıkıcı bulunmasını engellemek', 'Stüdyoda kurulan yapay dekorların gerçek mekânlardan ayırt edilmemesini garanti altına almak', 'Sessiz çekilen belgesel görüntülerine sonradan eklenecek senfonik müzik için uygun duraklamalar yaratmak'], 'Drew Associates, önemli bir karar ya da yarışma anındaki (seçim, idam kararı, konser, yarış) karakterleri izleyerek müdahalesiz gözleme dramatik bir yay kazandırmıştır.'),
  ('Luis Buñuel\'in İspanya\'nın yoksul Hurdes bölgesini konu alan 1933 tarihli Ekmeksiz Toprak filmi, aşırı abartılı ve soğukkanlı dış sesiyle hangi kipin eleştirel öncülerinden sayılır?', 'Düşünümsel kip', ['Gözlemci kip', 'Şiirsel kip', 'Katılımcı kip'], 'Buñuel, Ekmeksiz Toprak\'ta gezi ve etnografya belgesellerinin otoriter dış sesini parodileştirerek izleyicinin belgesel temsiline duyduğu güveni sarsmıştır.'),
  ('Marlon Riggs\'in Siyah gey kimliğini şiir, dans, müzik ve kişisel tanıklıkla işlediği 1989 yapımı Tongues Untied filmi Bill Nichols tarafından hangi kipin dönüm noktası olarak gösterilir?', 'Edimsel kip', ['Gözlemci kip', 'Açıklayıcı kip', 'Şiirsel kip'], 'Tongues Untied, nesnel mesafe yerine bedensel deneyimi, ritmi ve kimlik politikasını merkeze koyarak edimsel kipin kurucu örneklerinden biri olmuştur.'),
  ('Trinh T. Minh-ha\'nın Vietnamlı kadınlarla yapılan sahnelenmiş görüşmeler üzerinden etnografik belgesel kalıplarını yapıbozuma uğrattığı 1989 yapımı düşünümsel filmi hangisidir?', 'Surname Viet Given Name Nam', ['Chronicle of a Summer', 'Salesman', 'Harlan County, USA'], 'Surname Viet Given Name Nam, röportajın doğallığı ve antropolojik nesnellik iddiasını sorgulayan en önemli düşünümsel ve feminist belgesellerden biridir.'),
  ('Jean Rouch\'un etnografik sinemada geliştirdiği "paylaşılan antropoloji" (anthropologie partagée) ve geri bildirim yöntemi neyi içerir?', 'Çekilen görüntülerin filmdeki öznelere izletilerek onların yorum ve eleştirilerinin de yapım sürecine katılmasını', ['Yönetmenin yerel halkla hiçbir temas kurmadan uzaktan teleobjektiflerle gizli çekim yapmasını', 'Antropolojik verilerin yalnızca akademik kurullarda yazılı rapor olarak sunulup filmin halka kapatılmasını', 'Yerel kültürlere ait ritüellerin Avrupalı tiyatro oyuncuları tarafından stüdyoda yeniden canlandırılmasını'], 'Rouch, çektiği materyali öznelerle birlikte izleyip onların tepkilerini yeni bir katman olarak değerlendirmiş; Bir Yazın Kroniği\'nde de bu yöntemi uygulamıştır.'),
  ('Gözlemci belgesel kipine yöneltilen en temel etik eleştirilerden biri aşağıdakilerden hangisidir?', 'Mahrem ya da acı verici anlarda müdahalesizlik ilkesinin röntgenciliğe ve öznelerin rızasının belirsizleşmesine yol açabilmesi', ['Tanrısal dış sesin izleyicinin tüm politik bilincini tek taraflı devlet propagandasıyla baskı altına alması', 'Yönetmenin sürekli kendi kişisel anılarını anlatarak kameranın karşısındaki toplumsal özneleri hiç göstermemesi', 'Aşırı hızlı avangart kurgu nedeniyle izleyicinin filmdeki tarihsel olayların kronolojisini takip edememesi'], 'Gözlemci kipte kameranın mahrem kurumlarda veya kriz anlarında sessizce kayda devam etmesi, bilgilendirilmiş onam ve röntgencilik tartışmalarını doğurmuştur.'),
  ('Fransızca "canlı" veya "doğrudan" anlamına gelen ve 1960\'larda Kanada Ulusal Film Kurulu\'ndaki Frankofon sinemacıların taşınabilir senkron ses akımına verdiği ad nedir?', 'Cinéma direct', ['Kino-Pravda', 'Yeni Gerçekçilik', 'Dogma 95'], 'Michel Brault ve Pierre Perrault gibi Kanadalı Frankofon belgeselciler, müdahale ve gözlemi harmanlayan yaklaşımlarını "cinéma direct" olarak adlandırmıştır.'),
  ('Kanadalı görüntü yönetmeni Michel Brault\'nun geniş açılı elde kamera tekniğini Jean Rouch ile birleştirerek Fransız Cinéma Vérité estetiğini şekillendirdiği film hangisidir?', 'Bir Yazın Kroniği', ['Kuzeyli Nanook', 'Gece ve Sis', 'İnce Mavi Çizgi'], 'Kanada\'da elde yürüyen kamera tekniğini geliştiren Michel Brault, Rouch ve Morin\'in davetiyle Bir Yazın Kroniği\'ni çekerek görsel dili dönüştürmüştür.'),
  ('Taşınabilir senkron ses devrimi öncesinde (1930-1950 arası) belgesellerde açıklayıcı kipin ve dış sesin egemen olmasının başlıca teknik nedeni neydi?', '35 mm kameraların ve optik ses kayıt ekipmanlarının sahada doğal diyaloğu yakalayamayacak kadar ağır ve hantal olması', ['Dönemin film şeritlerinin insan sesindeki orta frekansları fiziksel olarak kaydetme yeteneğinden yoksun bulunması', 'Uluslararası sinema sendikalarının belgesellerde sıradan insanların kendi sesleriyle konuşmasını yasaklaması', 'Kurgu masalarında ses kuşağı ile görüntü kuşağını aynı anda kesebilecek mekanik makasların henüz icat edilmemesi'], 'Ağır kameralar ve kamyon gerektiren optik ses sistemleri doğaçlama saha kaydını zorlaştırdığı için görüntüler sessiz çekilip stüdyoda dış ses ve müzik ekleniyordu.'),
  ('Michael Moore\'un Roger & Me veya Bowling for Columbine gibi filmlerinde şirket yöneticilerinin karşısına habersiz çıkması Bill Nichols\'ın hangi kipinin kışkırtıcı kullanımına örnektir?', 'Katılımcı kip', ['Gözlemci kip', 'Şiirsel kip', 'Düşünümsel kip'], 'Moore\'un kamera önünde bizzat yer alarak muhataplarını sıkıştırması, karşılaşma anını dramatik çatışmaya dönüştüren popüler bir katılımcı kip stratejisidir.'),
  ('Errol Morris\'in cinayet suçlamasıyla hüküm giyen Randall Dale Adams vakasını çelişkili tanıklıklar ve stilize canlandırmalarla inceleyerek gerçeğin kurgusallığını sorguladığı 1988 yapımı belgesel hangisidir?', 'İnce Mavi Çizgi', ['Savaşın Sisi', 'Gri Bahçeler', 'Kameramlı Adam'], 'İnce Mavi Çizgi (The Thin Blue Line), farklı tanık anlatılarını stilize yeniden canlandırmalarla çarpıştırarak hem katılımcı hem düşünümsel kipin sınırlarını genişletmiştir.'),
  ('Errol Morris\'in röportaj yaptığı kişilerin doğrudan objektifin içine, dolayısıyla izleyicinin gözlerinin içine bakmasını sağlamak için geliştirdiği aygıtın adı nedir?', 'Interrotron', ['Steadicam', 'Kinoglaz', 'Aaton'], 'Morris\'in tasarladığı Interrotron, teleprompter aynaları yardımıyla yönetmenin yüzünü objektif önüne yansıtarak konuğun doğrudan kameraya bakarak konuşmasını sağlar.'),
  ('Leni Riefenstahl\'ın 1934 Nürnberg Nazi Partisi Kongresi\'ni görkemli kamera açılarıyla yücelten ancak tek bir dış ses yorumu bile kullanmayan tartışmalı propaganda belgeseli hangisidir?', 'İradenin Zaferi', ['Olympia', 'Gece ve Sis', 'Neden Savaşıyoruz'], 'İradenin Zaferi (Triumph des Willens), açıklayıcı dış ses kullanmadan yalnızca mizansen, kurgu ve tören düzeniyle ideolojik söylem kuran çarpıcı bir örnektir.'),
  ('Alain Resnais\'nin Nazi toplama kamplarının bugünkü sessiz kalıntılarını siyah-beyaz arşiv görüntüleri ve Jean Cayrol\'un edebi metniyle birleştirdiği 1956 tarihli belgeseli hangisidir?', 'Gece ve Sis', ['Shoah', 'Keder ve Acıma', 'Sıradan Faşizm'], 'Gece ve Sis (Nuit et brouillard), renkli çağdaş çekimlerle siyah-beyaz arşiv görüntülerini karşılaştırarak bellek ve tarihsel sorumluluk üzerine şiirsel-açıklayıcı bir yapı kurar.'),
  ('Claude Lanzmann\'ın 9,5 saatlik Holokost belgeseli Shoah (1985), tarihsel temsil açısından hangi radikal biçimsel tercihiyle öne çıkar?', 'Hiçbir tarihsel arşiv görüntüsü veya canlandırma kullanmadan yalnızca hayatta kalanların, faillerin ve tanıkların şimdiki zamandaki sözlerine dayanmasıyla', ['Tüm tanıklıkları profesyonel tiyatro oyuncularına siyah-beyaz sessiz film estetiğiyle yeniden canlandırmasıyla', 'Arşiv filmlerini yapay olarak renklendirip üzerine kesintisiz bir senfonik ağıt ve tanrısal dış ses yerleştirmesiyle', 'Yalnızca Müttefik ordularının resmi askeri haber filmlerini kronolojik sırayla kurgulayarak sunmasıyla'], 'Lanzmann, arşiv görüntüsü kullanmayı reddederek katılımcı görüşmeler aracılığıyla geçmişin travmasını şimdiki zamanda söz ve mekân üzerinden yeniden çağırmıştır.'),
  ('Katılımcı belgeselde kullanılan "sözlü tarih ve tanıklık" (testimony) görüşmeleri, açıklayıcı kipteki röportaj kullanımından nasıl ayrılır?', 'Katılımcı kipte görüşmeler filmin ana omurgasını ve yönetmen-özne karşılaşmasını oluştururken açıklayıcı kipte dış sesin tezini destekleyen ikincil kanıt işlevi görür', ['Katılımcı kipte konuşmacıların sesleri tamamen kısılıp yerine spiker sesi konurken açıklayıcı kipte yalnızca ham saha sesi kullanılır', 'Katılımcı kipte yalnızca anonim istatistik uzmanları konuşurken açıklayıcı kipte sadece yönetmenin aile bireyleri yer alır', 'Katılımcı kipte görüşmeler gizli kamerayla uzaktan çekilirken açıklayıcı kipte tüm sorular doğaçlama sokak sohbetleriyle gelişir'], 'Açıklayıcı kipte mülakatlar üst anlatıcının argümanına tabidir; katılımcı kipte ise sinemacı ile toplumsal aktör arasındaki diyalog bizzat bilginin kaynağıdır.'),
  ('Sahte belgesel (mockumentary) türündeki filmler, izleyici üzerinde inandırıcılık etkisi yaratmak için belgesel kuramı açısından neyi taklit eder ve açığa çıkarır?', 'Sarsıntılı el kamerası, uzman röportajı ve arşiv görüntüsü gibi belgesel gerçeklik kodlarının aslında taklit edilebilir birer biçimsel uzlaşım olduğunu', ['Belgesel sinemanın hiçbir kurgu veya çerçeveleme işlemi yapılmadan ham gerçekliği doğrudan perdeye aktardığını', 'Yalnızca 35 mm selüloit filmle çekilen görüntülerin tarihsel belge niteliği taşıyabileceğini', 'Tanrısal dış ses kullanılmadığında izleyicinin ekrandaki hiçbir görüntüyü ciddiye almadığını'], 'Sahte belgeseller, belgeselin "gerçeklik etkisi" yaratan kodlarını kurmaca içerikle kullanarak düşünümsel kipe benzer biçimde temsilin kurgusallığını ifşa eder.'),
  ('İkinci Dünya Savaşı sırasında Amerikan askerlerine savaşa girme gerekçelerini açıklamak amacıyla Frank Capra yönetiminde hazırlanan ve açıklayıcı kipin klasik örneği olan dizi hangisidir?', 'Why We Fight', ['The March of Time', 'Housing Problems', 'Listen to Britain'], 'Why We Fight (Neden Savaşıyoruz) serisi, düşman arşivlerini bile yeniden kurgulayıp otoriter dış sesle birleştirerek devlet politikasını savunan klasik açıklayıcı belgeseldir.'),
  ('İkinci Dünya Savaşı yıllarında İngiltere\'deki gündelik yaşamı hiçbir dış ses anlatımı olmadan ses ve görüntü kolajıyla betimleyen Humphrey Jennings ve Stewart McAllister imzalı belgesel hangisidir?', 'Listen to Britain', ['Night Mail', 'Coal Face', 'Drifters'], 'Listen to Britain (1942), fabrika gürültülerinden Mozart konserine uzanan ses-görüntü montajıyla şiirsel ve gözlemsel eğilimleri birleştirmiştir.'),
  ('1950\'lerin ortasında İngiltere\'de Lindsay Anderson, Karel Reisz ve Tony Richardson\'ın öncülük ettiği, sıradan işçi sınıfı insanlarının gündelik yaşamına odaklanan belgesel hareketi hangisidir?', 'Free Cinema', ['Cinéma Vérité', 'Direct Cinema', 'Yeni Nesnellik'], 'Free Cinema (Özgür Sinema), Grierson geleneğinin kurumsal didaktizmine karşı çıkarak hafif kameralarla gündelik hayatı şiirsel ve kişisel bir bakışla gözlemlemiştir.'),
  ('Taşınabilir 16 mm kameralarda omuzda taşımaya uygun ergonomik tasarımın (örneğin Éclair NPR ve Arriflex 16BL) geliştirilmesi belgesel estetiğinde hangi görsel değişimi yaratmıştır?', 'Kameranın insan gözü hizasında kalabalıkların içine karışarak öznel ve bedensel bir yakınlık hissi üretmesini sağlamıştır', ['Geniş açılı objektiflerin kullanımını imkânsız hale getirerek yalnızca sabit genel plan çekimlerini zorunlu kılmıştır', 'Alan derinliğini tamamen ortadan kaldırarak arka plandaki toplumsal çevrenin seçilmesini engellemiştir', 'Çekim sürelerini en fazla on beş saniyelik mekanik kurmalı planlarla sınırlandırmıştır'], 'Sessiz çalışan (self-blimped) ve omuza oturan Éclair NPR gibi kameralar, kameramanın insanlarla birlikte yürüyüp dar iç mekânlarda samimi planlar yakalamasını sağlamıştır.'),
  ('Fransız mühendis André Coutant tarafından geliştirilen ve 1960\'ların başında Cinéma Vérité sinemacılarının gözdesi olan sessiz çalışan omuz kamerası hangisidir?', 'Éclair NPR', ['Mitchell BNC', 'Bell & Howell Eyemo', 'Cinématographe'], 'Éclair NPR (Noiseless Portable Reflex), harici ses yalıtım kutusuna gerek duymadan omuzda taşınabilen ve hızlı kaset değiştirebilen devrimci bir 16 mm kameraydı.'),
  ('Bill Nichols\'a göre belgesel sinemayı kurmaca sinemadan ayıran en temel özellik teknik araçlardan ziyade hangi düzlemde yer alır?', 'Görüntülerin tarihsel dünyaya referans verme biçimi ile yönetmen, özne ve izleyici arasındaki etik-kurumsal sözleşmede', ['Belgesellerin yalnızca siyah-beyaz ve düşük bütçeli amatör kameralarla çekilme zorunluluğunda', 'Kurmaca filmlerde kurgu yapılırken belgesellerde çekilen planların sırasının asla değiştirilmemesinde', 'Belgesel sinemada müzik, ses tasarımı ve renk düzeltme gibi post-prodüksiyon işlemlerinin hiç uygulanmamasında'], 'Nichols, belgeseli kurmacayla aynı sinemasal araçları kullanmasına rağmen "kurmaca bir dünya" yerine doğrudan paylaştığımız "tarihsel dünya" hakkında söz söylemesiyle ayırır.'),
  ('Bir belgeselde yönetmen, arşiv görüntüsünün aslında başka bir savaşa ait olduğunu ve haber bültenlerinin izleyiciyi nasıl yanılttığını bizzat kurgu hilelerini bozarak gösteriyorsa hangi iki kip kesişir?', 'Açıklayıcı ve düşünümsel kipler', ['Gözlemci ve şiirsel kipler', 'Yalnızca saf gözlemci kip', 'Şiirsel ve gözlemci kipler'], 'Medya temsillerinin nasıl kurulduğunu analiz edip sinemasal uzlaşımları yapıbozuma uğratmak düşünümseldir; bunu doğrudan argümanla sunmak açıklayıcı kipten de pay alır.'),
  ('Barbara Kopple\'ın Kentucky\'deki maden işçilerinin grevini bir yıldan uzun süre sahada kalarak çektiği, gözlem ile katılımcı dayanışmayı birleştiren 1976 tarihli Oscar ödüllü belgeseli hangisidir?', 'Harlan County, USA', ['Salesman', 'Primary', 'Gimme Shelter'], 'Harlan County, USA, Doğrudan Sinema\'nın yakın gözlem tekniğini grevci madencilerle kurulan doğrudan etkileşim ve mülakatlarla birleştirmiştir.'),
  ('Maysles Kardeşler ve Charlotte Zwerin\'in Rolling Stones\'un Altamont ücretsiz konserindeki şiddet olaylarını ve bir cinayet anını kameralarla kaydettiği 1970 yapımı Doğrudan Sinema filmi hangisidir?', 'Gimme Shelter', ['Monterey Pop', 'Woodstock', 'Dont Look Back'], 'Gimme Shelter, kurgu masasında Mick Jagger\'ın cinayet kaydını izlediği sahneyle Doğrudan Sinema\'nın gözlemci sınırlarını öz-düşünümsel bir gerilimle buluşturmuştur.'),
  ('Esfir Şub\'un Çarlık dönemi arşivlerini Çarlığı övmek yerine eleştirmek için kurgulaması Bill Nichols\'ın kuramı açısından neyi kanıtlar?', 'Arşiv görüntülerinin sabit ve tekil bir anlam taşımadığını; kurgu bağlamı ve söylemsel çerçeve değiştiğinde karşıt bir tarihsel argümana hizmet edebildiğini', ['Tarihsel film kayıtlarının kurgu masasında kesildiğinde kimyasal olarak bozulup izlenemez hale geldiğini', 'Sessiz dönemde çekilen haber filmlerinin yalnızca doğa manzaralarından ibaret olduğunu', 'Arşiv belgesellerinin yalnızca gözlemci kipin kuralları çerçevesinde üretilebileceğini'], 'Derleme belgeselleri, indeksikal kaydın anlamının görüntünün kendisinden ziyade montaj ilişkisi ve üst çerçeveleme tarafından üretildiğini çarpıcı biçimde gösterir.'),
  ('1960\'larda geliştirilen "hızlı" (yüksek ASA/ISO duyarlılıklı) 16 mm film stokları taşınabilir senkron ses devrimine nasıl katkıda bulunmuştur?', 'Ağır stüdyo projektörleri kurmadan mevcut doğal iç mekân ışığında çekim yapılmasına olanak tanıyarak ortamın doğallığını korumuştur', ['Filmin banyo edilmesine gerek kalmadan çekim biter bitmez televizyonda canlı yayınlanmasını sağlamıştır', 'Kamera motorunun çıkardığı mekanik sesi tamamen emerek ses yalıtımına olan ihtiyacı ortadan kaldırmıştır', 'Siyah-beyaz çekilen negatiflerin karanlık odada kendiliğinden üç boyutlu holograma dönüşmesini sağlamıştır'], 'Yüksek ışık duyarlılıklı film emülsiyonları sayesinde belgeselciler hantal ışık ayakları ve kablolarla insanları tedirgin etmeden loş odalarda bile çekim yapabilmiştir.'),
  ('Jean Rouch ve Edgar Morin\'in Bir Yazın Kroniği filminin finalinde, filmde yer alan kişilerin sinema salonunda kendi görüntülerini izleyip "yapmacık mıydık, gerçek miydik?" diye tartışması hangi iki kipi buluşturur?', 'Katılımcı ve düşünümsel kipler', ['Şiirsel ve açıklayıcı kipler', 'Yalnızca klasik açıklayıcı kip', 'Saf gözlemci ve şiirsel kipler'], 'Öznelerin sürece dahil edilip görüş bildirmesi katılımcıdır; kameranın insan davranışı üzerindeki etkisinin ve "sinemasal gerçekliğin" bizzat film içinde tartışılması ise düşünümseldir.'),
  ('Amerikalı gazeteci ve yapımcı Robert Drew, Doğrudan Sinema anlayışını geliştirirken hangi basın mecrasındaki foto-röportaj geleneğinden ilham almıştır?', 'Life dergisinin anı yakalayan samimi foto-gazetecilik anlayışından', ['Radyo tiyatrolarının stüdyo içi ses efektleri geleneğinden', 'Ortaçağ el yazmalarındaki minyatür resimleme sanatından', 'Telgraf ajanslarının yalnızca borsa rakamlarını bildiren bültenlerinden'], 'Life dergisinde editörlük yapan Robert Drew, fotoğrafçıların yakaladığı doğal anları sinemaya taşımak istemiş ve sözün değil eylemin anlattığı "hareketli foto-röportaj" idealini kurmuştur.'),
  ('Bir belgeselde spiker "kentlerde yalnızlık giderek artıyor" derken kalabalık caddede tek başına yürüyen rastgele bir yayanın yüzüne kesme yapılması hangi etik ve biçimsel sorunu doğurur?', 'Kamusal alandaki bir bireyin rızası ve gerçek yaşam öyküsü bilinmeden dış sesin kurduğu kavramsal etiketin görsel kanıtı haline getirilmesini', ['Gözlemci kipte kesinlikle yasak olan geniş açılı objektif kullanımının ihlal edilmesini', 'Senkron ses kaydında kristal hız kontrolünün devre dışı kalarak dudak uyumunu bozmasını', 'İzleyicinin caddedeki mimari yapıların hangi yüzyılda inşa edildiğini anlayamamasını'], 'Açıklayıcı kipte rastgele seçilen B-roll planları, gerçekte çok mutlu olabilecek bir yayayı "yalnız insan" klişesine dönüştürerek temsil etiği sorunu yaratabilir.'),
  ('Taşınabilir senkron ses devrimi, belgesel sinemada "konuşma ve dil"in statüsünü nasıl dönüştürmüştür?', 'Eğitimli spikerin standart ve kitabi dili yerine sıradan insanların aksanlarını, duraksamalarını ve gündelik konuşma ritmini sinemanın merkezine taşımıştır', ['Belgesel filmlerde sözlü iletişimi tamamen ortadan kaldırıp yalnızca pandomim ve beden dilini geçerli kılmıştır', 'Farklı yörelerden insanların konuşmalarının mutlaka devlet radyosundaki spikerler tarafından yeniden seslendirilmesini sağlamıştır', 'Saha çekimlerinde kaydedilen tüm diyalogların yalnızca yazılı ara kartlar halinde ekrana basılmasına yol açmıştır'], 'Nagra ve taşınabilir kameralar sayesinde işçilerin, politikacıların, gençlerin ve sokaktaki insanların kendi ses tonları ve doğal konuşmaları ilk kez kesintisiz biçimde duyulmuştur.'),
  ('İranlı yönetmen Abbas Kiyarüstemi\'nin kendisini ünlü yönetmen Muhsin Mahmelbaf olarak tanıtan Hüseyin Sabzian\'ın gerçek mahkeme sürecini ve aileyle karşılaşmasını sahnelemelerle harmanladığı 1990 yapımı başyapıt hangisidir?', 'Yakın Plan', ['Kirazın Tadı', 'Rüzgâr Bizi Sürükleyecek', 'Arkadaşımın Evi Nerede'], 'Yakın Plan (Close-Up / Nema-ye Nazdik), gerçek yargılama kayıtları ile bizzat gerçek kişilerin kendilerini oynadığı yeniden canlandırmaları iç içe geçirerek belgesel-kurmaca sınırını düşünümsel biçimde eritir.'),
  ('Chantal Akerman\'ın New York\'ta yaşadığı dönemden görüntüler üzerine annesinin Brüksel\'den gönderdiği mektupları kendi sesiyle okuduğu 1977 yapımı minimalist film, hangi kiplerin kesişiminde yer alır?', 'Şiirsel, düşünümsel ve edimsel kipler', ['Yalnızca tanrısal dış sesli açıklayıcı kip', 'Yalnızca kriz yapısına dayalı Doğrudan Sinema', 'Sadece kurumsal derleme propaganda kipi'], 'News from Home, sabit ve uzun kent planları üzerine okunan kişisel mektuplarla görüntü ve ses arasındaki mesafeyi açarak şiirsel, düşünümsel ve öznel-edimsel bir alan kurar.'),
  ('1960\'larda belgesel kameralarında yaygınlaşan "zoom" (değişken odaklı) objektifler, gözlemci sinemacılara çekim anında hangi pratik avantajı sağlamıştır?', 'Kameraman yerini değiştirip olayın akışını bozmadan genel plandan yüzdeki duygusal bir ayrıntıya anında yaklaşabilme olanağı vermiştir', ['Karanlıkta kızılötesi termal görüntüleme yaparak duvarların arkasındaki insanları çekebilmeyi sağlamıştır', 'Kamera sarsıntısını tamamen yok ederek vinç ve ray kullanılmış izlenimi uyandırmıştır', 'Aynı anda hem önündeki hem arkasındaki alanı 360 derece panoramik olarak kaydetmiştir'], 'Angénieux gibi hafif 16 mm zoom lensler, gözlemci kameramanın insanlara fiziksel olarak sokulup onları rahatsız etmeden yakın plan tepkiler yakalamasını kolaylaştırmıştır.'),
  ('Gözlemci belgesellerde "şimdiki zaman kipi" hissinin bu denli güçlü olmasının temel biçimsel nedeni nedir?', 'Geçmişi özetleyen üst anlatıcı veya arşiv sıçramaları yerine olayların kamera önünde anbean oluşurken gerçek süresine yakın biçimde izlenmesi', ['Ekranın köşesinde çekim gününün saat ve saniyesini gösteren dijital bir kronometrenin sürekli yanıp sönmesi', 'Filmin sinema salonlarında değil yalnızca olay anında televizyondan canlı yayın olarak gösterilmesi', 'Bütün sahnelerin saniyede altmış kare hızlandırılmış çekimle kaydedilmesi'], 'Gözlemci kip, her şeyi önceden bilen dış sesi kaldırıp izleyiciyi olayın nereye varacağını karakterlerle eşzamanlı bekleyen bir tanık konumuna yerleştirir.'),
  ('Belgesel kuramında "bilgilendirilmiş onam" (informed consent) ilkesi neyi ifade eder?', 'Filmde yer alan kişilerin çekimin amacı, olası yayım bağlamı ve kendileri üzerindeki muhtemel sonuçları hakkında dürüstçe bilgilendirilerek rızalarının alınmasını', ['İzleyicilerin sinema salonuna girmeden önce filmin bütün kurgu senaryosunu okuyup imzalamasını', 'Yalnızca devlet memurlarının ve akademisyenlerin belgesellerde konuşmasına izin verilmesini', 'Kameramanın çekim yapacağı sokaktaki bütün binaların mimari planlarını belediyeye onaylatmasını'], 'Belgesel özneleri tarihsel dünyadaki gerçek bireyler olduğundan, görüntülerinin nasıl kullanılacağını bilerek rıza göstermeleri belgesel etiğinin temel taşlarından biridir.'),
  ('Katılımcı belgeselde yönetmenin arşiv görüntülerini veya eski gazete haberlerini elindeki bir ekrandan röportaj konuğuna izletip o andaki tepkisini kaydetmesi hangi işlevi görür?', 'Geçmişteki belge ile şimdiki zamandaki hafıza ve vicdanı çarpıştırarak canlı bir yüzleşme ve anlam üretimi sağlamayı', ['Açıklayıcı kipte olduğu gibi konuğun sesini tamamen kısıp yalnızca spikerin yorumunu öne çıkarmayı', 'Gözlemci kipin müdahalesizlik kuralına harfiyen uyarak kameranın varlığını gizlemeyi', 'Şiirsel kipte olduğu gibi tarihsel bağlamı silip yalnızca renk uyumuna odaklanmayı'], 'Katalizör olarak kullanılan arşiv malzemesi, katılımcı kipte geçmişi donmuş bir bilgi olmaktan çıkarıp şimdiki zamanda duygusal veya politik bir hesaplaşmaya dönüştürür.'),
  ('Joris Ivens ve Henri Storck\'un 1933\'te Belçika\'daki maden işçilerinin grevini ve yoksulluğunu gizli ve taşınabilir kameralarla belgelediği toplumsal belgesel klasiği hangisidir?', 'Misère au Borinage', ['Berlin: Büyük Bir Şehrin Senfonisi', 'Primary', 'Listen to Britain'], 'Misère au Borinage (Borinage\'da Sefalet), işçilerle birlikte grev yürüyüşünü yeniden canlandırması ve angaje bakışıyla politik-katılımcı belgesel geleneğinin öncülerindendir.'),
  ('1935-1951 yılları arasında ABD\'de sinemalarda gösterilen, haber görüntülerini dramatik dış ses ("Time marches on!") ve canlandırmalarla birleştiren açıklayıcı haber-belgesel dizisi hangisidir?', 'The March of Time', ['Candid Eye', 'Cinéma Vérité', 'Free Cinema'], 'Time dergisi grubunun ürettiği The March of Time, gür ve otoriter dış sesiyle ("Voice of Doom") klasik açıklayıcı kipin kitle kültüründeki kalıbını belirlemiştir.'),
  ('"Dış ses" (voice-over) kullanımı yalnızca açıklayıcı kipe mi özgüdür, yoksa diğer kiplerde de farklı işlevlerle yer alabilir mi?', 'Diğer kiplerde de yer alabilir; örneğin şiirsel kipte lirik bir ton, düşünümsel kipte kuşkucu bir öz-eleştiri, edimsel kipte ise mahrem bir günlük sesi kurabilir', ['Yalnızca açıklayıcı kipe özgüdür; başka herhangi bir kipte tek bir cümlelik dış ses kullanılması filmi belgesel olmaktan çıkarır', 'Yalnızca gözlemci kipte zorunludur; diğer beş belgesel kipinde sözlü anlatım tamamen yasaklanmıştır', 'Sadece sessiz dönem filmlerine sonradan eklenen televizyon dublajlarında kullanılmasına izin verilir'], 'Nichols\'a göre belirleyici olan dış sesin varlığı değil tonu ve otorite biçimidir: her şeyi bilen didaktik dış ses açıklayıcı iken kırılgan, sorgulayan veya öznel dış ses düşünümsel ya da edimsel olabilir.'),
  ('Fransız Cinéma Vérité teriminin İngilizce konuşulan ülkelerde zaman zaman yanlışlıkla el kamerasıyla çekilen tüm gözlemci belgeseller için genel bir etiket gibi kullanılması hangi kavram karmaşasına yol açar?', 'Rouch\'un müdahaleci ve kışkırtıcı yaklaşımı ile Amerikalı Doğrudan Sinemacıların müdahalesiz gözlem ilkesi arasındaki temel felsefi farkın silikleşmesine', ['Sessiz dönem şehir senfonilerinin yanlışlıkla üç boyutlu bilgisayar animasyonu sanılmasına', 'Açıklayıcı doğa belgesellerinin tamamının Fransızca altyazıyla gösterilme zorunluluğu doğmasına', 'Nagra ses kayıt cihazlarının yalnızca Fransa sınırları içinde üretildiği yanılgısının yayılmasına'], 'İngilizcede günlük dilde "cinéma vérité" bazen her türlü doğal el kamerası estetiği için kullanılsa da sinema tarihinde Fransız Cinéma Vérité ile Amerikan Direct Cinema birbirine zıt müdahale ilkelerine dayanır.'),
  ('Bir belgeselci, kurumsal bir huzurevinde çekim yaparken hiçbir çalışanla röportaj yapmıyor, kurumun tarihçesini anlatan yazı koymuyor ve yalnız koridorlardaki günlük rutini uzun planlarla izliyorsa kimin üslubuna en yakındır?', 'Frederick Wiseman', ['Errol Morris', 'Michael Moore', 'Pare Lorentz'], 'Kurumların işleyişini dış ses, röportaj, müzik ve açıklayıcı altyazı olmadan uzun gözlemsel sekanslarla kurgulamak doğrudan Frederick Wiseman\'ın kurumsal Doğrudan Sinema üslubudur.'),
  ('Dziga Vertov\'un kardeşi ve Kameralı Adam dahil pek çok filminde yenilikçi kamera hareketlerini gerçekleştiren görüntü yönetmeni kimdir?', 'Mihail Kaufman', ['Michel Brault', 'Richard Leacock', 'Boris Kaufman'], 'Mihail Kaufman, Kameralı Adam\'da bizzat kadraj içinde çalışan "kameralı adam" olarak görünerek filmin düşünümsel yapısının merkezinde yer almıştır.'),
  ('1960\'ların taşınabilir senkron ses ekipmanlarında kameramanın vizörden bakarken aynı anda sesçinin Nagra teybindeki kayıt durumunu görebilmesini sağlayan uyarı sistemi ne işe yarıyordu?', 'Kamera veya teypten birinin hızı senkrondan çıktığında vizörde uyarı ışığı yakarak boşa film harcanmasını ve senkron kaybını önlüyordu', ['Röportaj yapılan kişinin doğru söyleyip söylemediğini nabız ölçümüyle tespit ediyordu', 'Ortam sıcaklığı düştüğünde kamera objektifini otomatik olarak ısıtıyordu', 'Çekilen görüntüleri anında siyah-beyaz fotoğrafa basıp yönetmene veriyordu'], 'Kablosuz kristal senkron veya kablolu sistemlerde vizör içi senkron uyarı göstergeleri ve dahili işaret ışıkları, saha çekimlerinde teknik güvenliği sağlamıştır.'),
  ('Çağdaş etkileşimli web belgeselleri (i-docs) doğrusal olmayan yapılarıyla izleyiciye hangi yeni konumu kazandırarak klasik açıklayıcı kipten uzaklaşır?', 'İzleyiciyi tek bir zorunlu argümanı baştan sona dinleyen pasif alıcı olmaktan çıkarıp arşiv ve tanıklıklar arasında kendi rotasını seçen aktif katılımcıya dönüştürür', ['İzleyicinin yalnızca yönetmenin belirlediği tanrısal dış sesi sesini hiç kısamadan dinlemesini zorunlu kılar', 'Görüntü ve sesi tamamen ayırarak belgesellerin yalnızca basılı kitap olarak okunmasına yol açar', 'Taşınabilir kameraların kullanımını sonlandırıp yalnızca stüdyo içi canlı tartışma programlarına izin verir'], 'Etkileşimli belgeseller, katılımcı ve düşünümsel kiplerin mirasını dijital ortama taşıyarak tekil doğrusal anlatı otoritesini parçalar.'),
  ('Fransız Yeni Dalga ile Cinéma Vérité arasında güçlü bağ kuran, Chris Marker\'ın 1962\'de Paris sokaklarında Cezayir Savaşı\'nın bitişi üzerine insanlarla yaptığı röportajlardan oluşan belgesel hangisidir?', 'Güzel Mayıs', ['Gece ve Sis', 'İradenin Zaferi', 'Koyaanisqatsi'], 'Chris Marker ve Pierre Lhomme\'un yönettiği Güzel Mayıs (Le Joli Mai), taşınabilir senkron ses olanaklarıyla Paris halkının politik ve kişisel dünyasını sorgulayan önemli bir Cinéma Vérité yapıtıdır.'),
  ('Belgesel kurgusunda sesin görüntüden birkaç saniye önce girmesi veya görüntüsü bittikten sonra devam etmesi (J-cut ve L-cut) özellikle hangi kiplerde konuşma akışını yumuşatmak için sıkça kullanılır?', 'Katılımcı ve açıklayıcı kiplerde', ['Yalnızca sessiz dönem derleme filmlerinde', 'Sadece sözsüz şiirsel şehir senfonilerinde', 'Yalnızca tek planlık kesmesiz gözlem filmlerinde'], 'Röportaj ve dış ses ağırlıklı katılımcı-açıklayıcı belgesellerde ses köprüleri (L-cut / J-cut), konuşan kafadan B-roll görüntülerine geçişi pürüzsüzleştirir.'),
  ('Kanadalı yönetmen Allan King\'in duygusal sorunlar yaşayan çocukların kaldığı bir tedavi merkezini haftalarca müdahalesiz gözlemlediği ve kendisinin "aktüalite draması" adını verdiği 1967 yapımı sarsıcı belgesel hangisidir?', 'Warrendale', ['Night Mail', 'Koyaanisqatsi', 'Sans Soleil'], 'Allan King, Warrendale ve A Married Couple gibi yapıtlarıyla Kanada\'da gözlemci sinemanın en yoğun duygusal yakınlık kuran örneklerini vermiştir.'),
  ('Gözlemci belgesellerde kameramanın çekim yaptığı ortamda günlerce hatta aylarca kalarak insanların kameraya alışmasını beklemesi hangi amaçla yapılır?', 'İlk günlerdeki kamera bilincini ve poz verme eğilimini azaltarak öznelerin doğal gündelik davranışlarına dönmesini sağlamak amacıyla', ['Film negatiflerinin ortamın nem ve sıcaklık değerlerine kimyasal olarak uyum sağlamasını beklemek amacıyla', 'Devlet kurumlarından çekim izni çıkana kadar kamerayı gizlice çantada saklamak amacıyla', 'Yönetmenin çekim yapmadan önce bütün karakterlerin biyografilerini roman olarak yazması amacıyla'], 'Uzun süreli saha varlığı (immersion), gözlemci ve etnografik sinemacıların kamera karşısındaki yapay çekingenliği aşmak için başvurduğu temel çalışma yöntemidir.'),
  ('Luis Buñuel\'in Ekmeksiz Toprak\'ından yıllar sonra Belçikalı yönetmenler Rémy Belvaux, André Bonzel ve Benoît Poelvoorde\'un bir seri katili takip eden belgesel ekibini kara mizahla kurgulayarak izleyiciyi suç ortaklığıyla yüzleştirdiği 1992 yapımı sahte-düşünümsel film hangisidir?', 'Man Bites Dog', ['Primary', 'Titicut Follies', 'Listen to Britain'], 'Man Bites Dog (C\'est arrivé près de chez vous), gözlemci belgesel ekibinin giderek şiddetin suç ortağına dönüşmesini hicvederek müdahalesizlik etiğine sert bir düşünümsel eleştiri yöneltir.'),
  ('1960\'larda 16 mm taşınabilir kameralarda "refleks vizör" (aynalı örtücü sistemi) bulunması belgesel kameramanına hangi kritik üstünlüğü kazandırmıştır?', 'Paralaks hatası olmadan tam olarak objektifin gördüğü çerçeveyi ve netlik alanını çekim anında gerçek zamanlı görmesini sağlamıştır', ['Siyah-beyaz filmi vizör içinden yapay olarak tam renkli görmesini sağlamıştır', 'Ses kayıt cihazına hiç ihtiyaç duymadan sesi doğrudan vizör camına kaydetmesini sağlamıştır', 'Gece karanlığında hiçbir ışık kaynağı olmadan gündüz gibi aydınlık görüntü almasını sağlamıştır'], 'Eski yan vizörlü kameralarda bakılan açı ile objektifin açısı tam örtüşmezken (paralaks), Éclair NPR ve Arriflex gibi refleks kameralar hareketli saha çekimlerinde kusursuz netlik ve kadraj kontrolü sunmuştur.'),
  ('Katılımcı belgeselde yönetmenin kamera arkasından sorduğu soruların kurguda kesilip yalnızca konuğun yanıtlarının bırakılması ("gizlenmiş mülakat") hangi estetik etkiyi hedefler?', 'Konuğun sanki bir soruya yanıt vermiyormuş da kendi iç dünyasını doğrudan izleyiciye kendiliğinden açıyormuş gibi kesintisiz bir monolog etkisi yaratmasını', ['Filmin düşünümsel kipin kurallarına uygun olarak bütün yapım sürecini açıkça sergilemesini', 'Tanrısal dış sesin konuğun bütün cümlelerini bastırarak tek otorite olarak kalmasını', 'Görüntü ile ses arasındaki senkronun bilinçli olarak kaydırılıp yabancılaştırma yapılmasını'], 'pek çok belgeselde yönetmenin sorusu kurguda çıkarılarak katılımcı karşılaşmanın izi örtülür ve konuğun tanıklığına özerk bir akış kazandırılır.'),
  ('Bill Nichols\'ın belgesel sınıflandırmasında tarihsel olarak 1920\'lerde ortaya çıkan ilk iki kip hangileridir?', 'Şiirsel kip ve açıklayıcı kip', ['Gözlemci kip ve edimsel kip', 'Katılımcı kip ve gözlemci kip', 'Düşünümsel kip ve edimsel kip'], '1920\'lerde avangart sinemayla birleşen şiirsel kip ile Grierson ve Flaherty çizgisinden gelişip 1930\'larda sesle pekişen açıklayıcı kip belgesel tarihinin en erken iki ana koludur.'),
  ('Taşınabilir senkron ses devriminin doğrudan mümkün kıldığı ve 1960 civarında olgunlaşan iki belgesel kipi Bill Nichols\'ın şemasında hangileridir?', 'Gözlemci kip ve katılımcı kip', ['Şiirsel kip ve açıklayıcı kip', 'Yalnızca açıklayıcı kip', 'Şiirsel kip ve edimsel kip'], 'Hafif 16 mm kameralar ve Nagra senkron teypler hem müdahalesiz izlemeye dayanan gözlemci kipin (Direct Cinema) hem de sahada canlı etkileşim ve söyleşiye dayanan katılımcı kipin (Cinéma Vérité) önünü açmıştır.'),
  ('ABD Yüksek Mahkemesi\'ne taşınan nadir belgesel sansür davalarından birine konu olan ve eyalet akıl hastanesindeki insanlık dışı koşulları gözlemci üslupla belgeleyen 1967 yapımı Frederick Wiseman filmi hangisidir?', 'Titicut Follies', ['High School', 'Hospital', 'Welfare'], 'Massachusetts eyaleti, mahremiyet ihlali gerekçesiyle Titicut Follies\'in genel gösterimini onlarca yıl kısıtlamış; film gözlemci belgeselde kamu yararı ile hasta mahremiyeti arasındaki en ünlü hukuk tartışması olmuştur.'),
  ('Bir doğa belgeselinde hayvan davranışlarının insan aile yapısına benzetilerek ("fedakâr anne penguen", "kıskanç rakip") duygusal müzik ve otoriter dış sesle anlatılması hangi kipin antropomorfik kullanımına örnektir?', 'Açıklayıcı kip', ['Düşünümsel kip', 'Gözlemci kip', 'Cinéma Vérité'], 'Klasik televizyon doğa belgesellerinin önemli bir bölümü, doğa görüntülerini insan merkezli ahlaki öyküler ve tanrısal dış sesle çerçeveleyen popüler açıklayıcı kip örnekleridir.'),
  ('Dijital çağda küçük el kameralarının ve akıllı telefonların yaygınlaşması, 1960\'lardaki 16 mm taşınabilir senkron ses devriminin mirasını hangi yönde radikalleştirmiştir?', 'Çekim maliyetini ve ekipman görünürlüğünü en aza indirerek belgesel üretimini profesyonel sinemacılardan bizzat olayın içindeki öznelerin birinci şahıs tanıklıklarına ve oto-etnografik kayıtlara açmıştır', ['Belgesellerde senkron ses kullanımını tamamen sona erdirip sessiz film estetiğini zorunlu hale getirmiştir', 'Gözlemci ve katılımcı kiplerin tamamen unutulup yalnızca büyük bütçeli stüdyo belgesellerinin çekilmesine yol açmıştır', 'Kurgu yazılımlarını ortadan kaldırarak çekilen hiçbir görüntünün kesilmesine izin vermemiştir'], '1960\'larda iki kişilik profesyonel ekibe inen hareket özgürlüğü, dijital kameralarla bizzat öznelerin kendi hayatlarını içeriden belgelediği katılımcı ve edimsel pratiklere evrilmiştir.'),
  ('Robert Flaherty\'nin 1922 yapımı "Kuzeyli Nanook" belgeselinde İnuit ailesine çoktan terk ettikleri geleneksel zıpkınla avlanma yöntemini kamera için tekrarlatması hangi etik tartışmanın ilk büyük örneğidir?', 'Sahneleme ve gerçekliğin inşası', ['Telifsiz müzik ve ses kullanımı', 'Gizli kamerayla özel hayat ihlali', 'Sponsorların kurguya müdahalesi'], 'Flaherty\'nin gerçekliği olduğu gibi kaydetmek yerine özneleri geçmişteki geleneklere göre yönlendirip sahnelemesi belgeselde kurmaca-gerçeklik sınırının temel tartışmalarındandır.'),
  ('Doğa belgesellerinde vahşi yaşam görüntüleri çok uzaktan teleobjektiflerle çekildiği için sahada kaydedilemeyen ayak sesi, kanat çırpışı veya çiğneme seslerinin stüdyoda sonradan üretilmesine ne ad verilir?', 'Foley ses tasarımı', ['Diegetik alan kaydı', 'Senkronize diyalog', 'Doğrudan ses kurgusu'], 'Uzak mesafeden yapılan doğa çekimlerinde mikrofonun yakalayamadığı doğa ve hayvan seslerinin stüdyoda yapay nesnelerle yeniden üretilmesi Foley tekniğidir.'),
  ('Belgesel kuramcısı Bill Nichols\'ın sınıflandırmasında, yönetmenin kamerayla görünmez bir "duvardaki sinek" gibi davrandığı ve röportaj ya da dış ses kullanmadığı kip hangisidir?', 'Gözlemsel kip (observational mode)', ['Açıklayıcı kip (expository mode)', 'Şiirsel kip (poetic mode)', 'Dönüşlü kip (reflexive mode)'], 'Yönetmenin müdahale etmeden, dış ses, müzik veya röportaj eklemeden olayları akışı içinde izlediği belgesel biçimi gözlemsel kiptir.'),
  ('"Tanrının Sesi" (Voice of God) olarak adlandırılan otoriter ve her şeyi bilen dış ses anlatıcısı, Bill Nichols\'ın hangi belgesel kipinin en belirgin özelliğidir?', 'Açıklayıcı kip (expository mode)', ['Katılımcı kip (participatory mode)', 'Edimsel kip (performative mode)', 'Gözlemsel kip (observational mode)'], 'Görüntüleri yönlendiren, izleyiciye ne düşünmesi gerektiğini söyleyen otoriter dış ses anlatımı açıklayıcı belgesel kipinin temel unsurudur.'),
  ('Errol Morris\'in röportaj yapılan kişinin hem görüşmecinin gözlerinin içine hem de doğrudan kamera merceğine aynı anda bakabilmesini sağlamak için geliştirdiği teleprompter tabanlı aygıtın adı nedir?', 'Interrotron', ['Steadicam', 'Kinematograf', 'Zoopraksiskop'], 'Interrotron, kamera merceğinin önüne yerleştirilen çift yönlü aynalarla yönetmenin yüzünü yansıtarak öznenin doğrudan izleyiciyle göz teması kurmasını sağlar.'),
  ('Bir tarih belgeselinde Birinci Dünya Savaşı\'ndaki Batı Cephesi anlatılırken farklı bir cepheye ve yıla ait arşiv görüntüsünün izleyiciye belirtilmeden kullanılması hangi etik sorunu doğurur?', 'Tarihsel bağlamın çarpıtılması', ['Görüntü çözünürlüğünün düşmesi', 'Ses senkronizasyonunun bozulması', 'Telif süresinin yeniden başlaması'], 'Arşiv görüntülerinin çekildiği yer ve zaman bağlamından koparılarak başka bir olayı kanıtlamak için kullanılması tarihsel gerçekliği yanıltır.'),
  ('1958 yapımı Disney doğa belgeseli "White Wilderness"ta kutup sıçanlarının (lemming) topluca uçurumdan atlayarak intihar ettiği efsanesinin yayılmasına yol açan büyük etik skandal nedir?', 'Hayvanların yapım ekibince uçurumdan itilmesi', ['Görüntülerin bilgisayar animasyonuyla üretilmesi', 'Kutup sıçanları yerine boyanmış fare kullanılması', 'Arşiv görüntülerinin tersten oynatılarak kurgulanması'], 'Yapım ekibi gerçekte göç etmeyen lemmingleri satın alıp döner platformlarla kayalıklardan suya iterek sahte bir toplu intihar sahnesi kurgulamıştır.'),
  ('Bir belgeselde röportaj veren kişinin uzun konuşmasından farklı cümle parçalarının alınıp birleştirilerek asıl kastettiğinden bambaşka bir anlam çıkarılmasına kurgu dilinde ne denir?', 'Frankenbiting (manipülatif ses kurgusu)', ['Jump-cut (sıçramalı görüntü kurgusu)', 'Cross-cutting (paralel kurgu tekniği)', 'Match-cut (eşleşmeli geçiş kurgusu)'], 'Öznenin farklı anlarda söylediği kelimelerin ses kurgusunda yapıştırılarak söylemediği bir cümle üretilmesine Frankenbiting denir ve ciddi bir etik ihlaldir.'),
  ('1960\'larda Kuzey Amerika\'da hafif el kameraları ve senkron ses kayıt cihazlarının gelişmesiyle ortaya çıkan, müdahalesiz gözlemi savunan belgesel akımı hangisidir?', 'Direct Cinema', ['İtalyan Yeni Gerçekçiliği', 'Alman Dışavurumculuğu', 'Fransız Şiirsel Gerçekçiliği'], 'Richard Leacock, Robert Drew ve Maysles kardeşlerin öncülük ettiği Direct Cinema, taşınabilir ekipmanlarla olayları müdahalesiz gözlemlemeyi amaçlamıştır.'),
  ('Bir bitkinin 30 günlük büyüme sürecini saniyede 24 kare oynatılacak 10 saniyelik kesintisiz bir time-lapse videosuna dönüştürmek isteyen görüntü yönetmeni toplam kaç fotoğraf karesi çekmelidir?', '240 kare', ['300 kare', '720 kare', '1440 kare'], 'Saniyede 24 kareden 10 saniyelik bir video elde etmek için 24 x 10 = 240 adet fotoğraf karesi çekilmesi gerekir.'),
  ('Bir belgeselde "konuşan kafa" röportajı sırasında öznenin kameranın hemen yanındaki görünmez görüşmeciye bakması ile doğrudan merceğe bakması izleyici algısında nasıl bir fark yaratır?', 'Doğrudan merceğe bakış izleyiciyle yüz yüze muhataplık kurar', ['Yana bakış öznenin yalan söylediği izlenimini kesinleştirir', 'Doğrudan merceğe bakış belgeseli kurmaca filme dönüştürür', 'Yana bakış görüntünün arşiv kaydı olduğunu kanıtlar'], 'Öznenin kamera yanına bakması üçüncü tekil gözlem hissi verirken, doğrudan merceğe bakması izleyiciyle aracısız ve yoğun bir yüzleşme duygusu yaratır.'),
  ('Doğa belgesellerinde yabani bir hayvanın doğada çekilmesi çok zor olan doğum veya avlanma anının hayvanat bahçesinde ya da özel sette çekilip vahşi doğadaymış gibi kurgulanması neden etik eleştiri alır?', 'İzleyiciye kontrolsüz doğa kaydı yanılsaması sunduğu için', ['Hayvanat bahçelerinin telif ücreti talep etmesi yüzünden', 'Stüdyo ışıklarının kamera sensörüne zarar vermesinden ötürü', 'Kapalı alan çekimlerinin çözünürlüğü düşürmesi nedeniyle'], 'Kontrollü ortamda çekilen görüntülerin şeffafça belirtilmeden vahşi doğada yakalanmış gibi sunulması izleyicinin belgesele duyduğu güven sözleşmesini zedeler.'),
  ('Orson Welles\'in 1973 yapımı "F for Fake" (Çakma) filmi, sanat sahtekarı Elmyr de Hory\'yi anlatırken yönetmenin izleyiciye kurmacalar kattığını açıkça söylemesiyle hangi türün öncüsü sayılır?', 'Deneme filmi ve dönüşlü belgesel', ['Gözlemsel doğa tarihi belgeseli', 'Sosyalist gerçekçi propaganda filmi', 'Gizli kameralı araştırmacı gazetecilik'], 'Orson Welles, hakikat ve aldatmaca kavramlarını bizzat belgeselin kendi kurgu oyunlarını ifşa ederek sorgulamış ve dönüşlü (reflexive) belgesel ile deneme filminin öncülerinden olmuştur.'),
  ('Araştırmacı bir belgeselde kamu yararını ilgilendiren ağır bir yolsuzluğu veya istismarı belgelemek için aydınlatılmış onam almadan gizli kamera kullanılması hangi koşulda etik olarak savunulabilir?', 'Bilgiyi başka yolla elde etme olanağı yoksa ve üstün kamu yararı varsa', ['Yapım şirketinin reyting ve gişe gelirini iki katına çıkarma hedefi varsa', 'Yönetmenin aydınlatma ekipmanı kuracak yeterli bütçesi bulunmuyorsa', 'Çekilen kişilerin sosyal medyada yüksek takipçi sayısına sahip olması halinde'], 'Gazetecilik ve belgesel etiğinde gizli çekim ancak ciddi bir suçu veya istismarı belgelemek için son çare olduğunda ve üstün kamu yararı bulunduğunda meşru görülür.'),
  ('Bir doğa belgeselcisi gece karanlığında avlanan leoparları doğal davranışlarını hiç bozmadan ve yapay görünür ışık yakmadan görüntülemek istediğinde hangi kamera teknolojisini tercih etmelidir?', 'Termal veya kızılötesi (infrared) kamera', ['Standart gün ışığı renkli film kamerası', 'Yüksek güçlü halojen spot projektörleri', 'Yalnızca geniş açılı su altı muhafazası'], 'Kızılötesi ve termal kameralar hayvanların gözünü kamaştıran görünür ışık yaymadan karanlıkta doğal davranışları kaydetmeye olanak tanır.'),
  ('Ari Folman\'ın 1982 Lübnan Savaşı\'na dair bastırılmış anılarını eski silah arkadaşlarıyla yaptığı gerçek röportajlar üzerinden anlattığı "Beşir\'le Vals" (2008) filmi, gerçeklik ile hafızayı buluşturmak için hangi görsel biçimi kullanmıştır?', 'Animasyon belgesel', ['Siyah-beyaz sessiz arşiv kolajı', 'Tek plan kesintisiz gözlemsel çekim', 'Gizli kamera ve gece görüş kaydı'], 'Beşir\'le Vals, görsel kaydı bulunmayan travmatik anıları, rüyaları ve halüsinasyonları gerçek ses kayıtları üzerine kurulu animasyon belgesel formuyla aktarmıştır.'),
  ('Reşit olmayan çocukların veya travma yaşamış kırılgan grupların belgesel öznesi olduğu yapımlarda "aydınlatılmış onam" sürecinin tek seferlik imzayla bitmemesi gerektiği görüşü neyi savunur?', 'Süreçsel onam ile özneye çekim ve kurgu aşamalarında cayma hakkı tanınmasını', ['Çocukların yerine mutlaka yetişkin profesyonel oyuncuların geçirilmesini', 'Onam belgesinin yalnızca yerel belediye meclisi tarafından imzalanmasını', 'Belgeselin tamamlandıktan sonra hiçbir film festivaline gönderilmemesini'], 'Kırılgan özneler çekimin uzun vadeli etkilerini başta öngöremeyebileceği için etik belgeselcilikte rızanın süreç boyunca teyit edildiği süreçsel onam yaklaşımı savunulur.'),
  ('"Kayıp Görüntü" (found footage) korku filmlerinden "The Blair Witch Project" (1999), kurmaca-gerçeklik sınırını bulanıklaştırmak için hangi belgesel stratejisini kullanmıştır?', 'Amatör belgeselcilerin kaybolduktan sonra bulunan ham kayıtlarıymış gibi sunulması', ['Ünlü tarih profesörleriyle üniversite kütüphanelerinde röportajlar yapılması', 'Devlet arşivlerinden alınan gerçek polis telsizi kayıtlarının altyazıyla verilmesi', 'Yavaş çekim doğa görüntüleri üzerine klasik batı müziği yerleştirilmesi'], 'Blair Cadısı Projesi, ormanda belgesel çeken öğrencilerin geride kalan gerçek kamera kasetleri olduğu iddiasıyla pazarlanarak sahte belgesel estetiğini korku sinemasına taşımıştır.'),
  ('Jacques-Yves Cousteau ve Louis Malle\'in 1956 yapımı "Sessiz Dünya" belgeseli, günümüz doğa belgeselciliği etiği açısından incelendiğinde hangi sahneleri nedeniyle ağır biçimde eleştirilmektedir?', 'Mercan resiflerinin dinamitlenmesi ve köpekbalıklarının güvertede öldürülmesi', ['Bütün su altı görüntülerinin dev stüdyo akvaryumlarında çekilmiş olması', 'Deniz canlılarının seslerinin ünlü seslendirme sanatçılarınca taklit edilmesi', 'Balık sürülerinin bilgisayar destekli görsel efektlerle çoğaltılması'], 'Döneminin çevreci bilincinin henüz gelişmemiş olması nedeniyle filmde bilimsel örnek toplama adına dinamit kullanılması ve köpekbalıklarının katledilmesi bugünkü doğa etiğiyle taban tabana zıttır.'),
  ('Bir tarih belgeseli yönetmeni, elinde yalnızca 19. yüzyıldan kalma mektuplar ve birkaç soluk portre fotoğrafı varken "konuşan kafalar"a başvurmadan dönemin duygusunu aktarmak isterse hangi yöntemi seçmelidir?', 'Mektupların seslendirilmesiyle mekan çekimlerini ve detay fotoğrafları birleştirmek', ['Farklı bir yüzyıla ait renkli televizyon haber görüntülerini araya serpiştirmek', 'Tarihçileri kamera karşısına oturtup mektupları akademik dille özetletmek', 'Hiçbir görsel ve işitsel öğe kullanmadan yalnızca akan yazı metni yayınlamak'], 'Dönem mekanlarının atmosferik görüntüleri ve portre detayları üzerine mektupların birinci tekil şahıs seslendirmesini eklemek konuşan kafalar olmadan güçlü bir tarihsel anlatım kurar.'),
  ('Luc Jacquet\'nin 2005 yapımı "İmparatorun Yolculuğu" (March of the Penguins) belgeselinin Fransızca orijinal versiyonunda penguenlerin birinci tekil şahısla birbirleriyle konuşuyormuş gibi seslendirilmesi hangi eleştiriyi doğurmuştur?', 'Vahşi yaşam gerçekliğini aşırı insanbiçimci bir masal diline indirgemesi', ['Penguenlerin göç rotasının yanlış kıtada çekilmiş görüntülerle gösterilmesi', 'Antarktika\'daki araştırma üslerinin askeri sırlarını izinsiz ifşa etmesi', 'Time-lapse tekniğinin saniyede çok fazla kareyle hatalı uygulanması'], 'Hayvanların insan sesiyle romantik diyaloglar kuruyormuş gibi konuşturulması, doğa belgeselinin bilimsel gözlem niteliğini zayıflatıp antropomorfizmi uç noktaya taşıdığı gerekçesiyle tartışılmıştır.'),
  ('Sovyet yönetmen Esfir Şub\'un 1927\'de tek bir yeni plan bile çekmeden, Çar II. Nikolay dönemine ait eski saray ve haber filmlerini yeniden kurgulayarak oluşturduğu "Romanov Hanedanının Çöküşü" hangi belgesel türünün öncüsüdür?', 'Derleme belgesel (compilation film)', ['Sahte belgesel (mockumentary)', 'Katılımcı belgesel (participatory)', 'Doğa tarihi belgeseli (wildlife film)'], 'Esfir Şub, yalnızca mevcut arşiv görüntülerini yeni bir ideolojik ve tarihsel bağlamda kurgulayarak derleme (arşiv) belgeselciliğinin kurucusu olmuştur.'),
  ('Doküdrama türünde çekilen bir televizyon dizisinde tarihsel kişiliklerin özel odalarında yaptıkları ikili konuşmaların senarist tarafından yazılması kurmaca-gerçeklik sınırında neyi gösterir?', 'Kamusal tarihsel olgular arasındaki boşlukların dramatik hayal gücüyle doldurulduğunu', ['Bütün tarihsel liderlerin odalarında kesintisiz ses kayıt cihazı bulunduğunu', 'Doküdramaların bilimsel tarih tezleriyle birebir aynı kanıt değerini taşıdığını', 'Oyuncuların çekim sırasında hiçbir senaryo metnine bağlı kalmadan doğaçlama yaptığını'], 'Doküdramalar bilinen tarihsel olayların iskeletini korurken, kaydı bulunmayan özel diyalogları ve duygusal anları dramatik kurmaca ilkeleriyle inşa eder.'),
  ('Bir belgeselcinin çekim yaptığı dezavantajlı mahalledeki insanları yalnızca sefalet, suç ve çaresizlik anlarıyla çerçeveleyip gündelik neşelerini ve dirençlerini kurguda tamamen dışarıda bırakması hangi etik eleştiriye konu olur?', 'Sefalet pornosu (poverty porn) ve tek boyutlu ötekileştirme', ['Aydınlatılmış onam formunun noter huzurunda imzalanmaması', 'Arşiv görüntülerinin yanlış kare hızında dijitalleştirilmesi', 'Time-lapse çekimlerinde doğal güneş ışığının kullanılması'], 'Öznelerin insanlık onurunu ve çok yönlü yaşamlarını yok sayarak acıyı izleyicinin acıma duygusunu sömürecek şekilde estetize etmek etik bir temsil sorunudur.'),
  ('Belgesel sinemada kameranın arkasındaki yönetmenin bizzat görüntüye girdiği, sorularının duyulduğu ve özneyle kurduğu karşılaşmanın filmin ana eksenini oluşturduğu Bill Nichols kipi hangisidir?', 'Katılımcı kip (participatory mode)', ['Gözlemsel kip (observational mode)', 'Şiirsel kip (poetic mode)', 'Açıklayıcı kip (expository mode)'], 'Katılımcı kipte yönetmen görünmez bir gözlemci değildir; röportaj yapan, etkileşime giren ve süreci kameranın önünde birlikte yaşayan bir aktördür.'),
  ('Bir belgesel kurgucusu "konuşan kafa" röportajındaki duraksamaları ve dil sürçmelerini temizlerken görüntüde oluşan sıçramaları (jump-cut) gizlemek ve anlatımı görsel olarak desteklemek için ne kullanır?', 'B-roll', ['Renk barları ve ses kalibrasyon tonu', 'Siyah ekran üzerinde telif uyarı yazısı', 'Ham senaryonun ekran görüntüsü'], 'Röportaj ses bandı altta akmaya devam ederken üstüne öznenin çalışma anı, arşiv fotoğrafları veya mekan detayları gibi B-roll görüntüleri yerleştirilerek kesmeler gizlenir.'),
  ('"Microcosmos" belgeselinin hemen başında çok kısa bir dış ses dışında film boyunca hiçbir bilimsel açıklama veya konuşan kafa kullanılmaması izleyici üzerinde nasıl bir etki amaçlar?', 'Doğayı didaktik bir ders malzemesi yerine saf duyusal ve görsel bir deneyim olarak yaşatmayı', ['İzleyicinin böcek türlerinin Latince bilimsel isimlerini kolayca ezberlemesini sağlamayı', 'Yapım şirketinin farklı ülkelere satış yaparken çeviri maliyetinden tamamen kurtulmasını', 'Böceklerin aslında bilgisayar ortamında çizilmiş sahte görüntüler olduğunu gizlemeyi'], 'Açıklayıcı dış sesi terk etmek, izleyiciyi ansiklopedik bilgiden uzaklaştırarak çayır ekosisteminin ritmine ve görsel şiirselliğine doğrudan ortak eder.'),
  ('1957\'de İngiliz televizyon programı Panorama\'nın 1 Nisan şakası olarak yayınladığı, İsviçre\'deki köylülerin ağaçlardan makarna topladığını ciddi bir haber belgeseli diliyle anlatan ünlü sahte belgesel hangisidir?', 'İsviçre Spagetti Hasadı', ['Dünyalar Savaşı Yayını', 'Karanlık Ay Operasyonu', 'Unutulmuş Gümüş'], 'BBC\'nin saygın haber programı Panorama\'da Richard Dimbleby\'nin ciddi dış sesiyle sunulan İsviçre Spagetti Hasadı, televizyon tarihinin en ünlü erken dönem mockumentary şakalarındandır.'),
  ('Tarih belgesellerinde sıkça görülen, yalnızca erkek akademisyenlerin kütüphane önünde "konuşan kafa" olarak seçilmesi ve olayın sıradan tanıklarının dışlanması temsil etiğinde hangi eleştiriyi alır?', 'Otorite yanlılığı ve çok sesli toplumsal hafızanın daraltılması', ['Kütüphane mekanlarının akustik yankı yaratarak sesi bozması', 'Akademisyenlerin kamera merceğine bakmaktan sürekli kaçınması', 'Kitap raflarının arka planda odak kaymasına neden olması'], 'Yalnızca kurumsal unvanlı tek tip uzmanlara söz vermek sözlü tarihi ve farklı toplumsal kesimlerin deneyimini görünmez kılarak resmi anlatıyı tekelleştirir.'),
  ('Woody Allen\'ın 1983 yapımı "Zelig" adlı sahte belgeselinde, girdiği her ortamda yanındaki insanların fiziksel ve ruhsal özelliklerine bürünen kurmaca karakteri 1920\'lerin gerçek arşiv görüntülerine yerleştirmek için hangi yöntem izlenmiştir?', 'Dönem kameraları ve yıpratılmış film stokuyla çekilip gerçek arşivlere optik olarak birleştirilmesi', ['1920\'lerde çekilmiş gerçek bir sessiz filmin isimlerinin altyazıda değiştirilmesi', 'Bütün tarihsel kişiliklerin balmumu heykellerinin müzede sabit kamerayla çekilmesi', 'Yalnızca radyo tiyatrosu kayıtları üzerine siyah ekran ve tarih yazıları konulması'], 'Görüntü yönetmeni Gordon Willis, 1920\'lerin antika merceklerini kullanıp negatifleri bilerek çizerek kurmaca çekimleri gerçek haber arşivleriyle kusursuzca kaynaştırmıştır.'),
  ('Sosyal medyada veya açık sokakta çekim yapan bir belgeselci, kamusal alanda bulunsa bile tek bir kişiyi uzun süre yakın planda takip edip özel telefon konuşmasını yönlü mikrofonla kaydederse hangi sınırı aşmış olur?', 'Kamusal alanda makul mahremiyet beklentisi ve haberleşme gizliliğini', ['Kamera bataryasının açık havada güvenli kullanım yönetmeliğini', 'Belgesel filmlerin maksimum 90 dakika olması yönündeki festival kuralını', 'Geniş açılı lenslerin şehir merkezinde kullanımına dair imar iznini'], 'Bir kişinin sokakta yürümesi her türlü özel konuşmasının gizlice dinlenip yayınlanabileceği anlamına gelmez; odaklanmış takip ve özel konuşma kaydı mahremiyet ihlalidir.'),
  ('Claude Lanzmann\'ın Holokost\'u konu alan 9,5 saatlik anıtsal belgeseli "Shoah" (1985), tarihsel temsilde hangi radikal etik ve estetik kararıyla diğer tarih belgesellerinden ayrılır?', 'Hiçbir arşiv görüntüsü ve canlandırma kullanmadan yalnızca tanıklıklara ve şimdiki zaman mekanlarına dayanması', ['Bütün olayları yalnızca dönemin siyah-beyaz propaganda arşivlerinden sessizce derlemesi', 'Tanıkların yüzlerini gizleyerek ifadeleri ünlü tiyatro oyuncularına stüdyoda okutması', 'Tarihsel olayları sembolik doğa görüntüleri ve klasik müzik eşliğinde anlatması'], 'Lanzmann, arşiv görüntülerinin ve canlandırmaların soykırımın kavranamaz dehşetini sıradanlaştıracağını savunarak tek kare arşiv kullanmadan sözlü tanıklığa başvurmuştur.'),
  ('Bir belgeselde farklı mevsimlerde ve birbirinden yüzlerce kilometre uzakta yaşayan iki ayrı boz ayının görüntülerinin kurguda "aynı anne ayının yaz boyu süren yolculuğu" diye birleştirilmesi doğa belgeselciliğinde neyin örneğidir?', 'Kompozit karakter oluşturarak dramatik öykü kurgulamanın', ['Boz ayıların doğal yaşam alanlarını koruma amaçlı gizlemenin', 'Kamera sensöründeki renk sapmalarını kurgu masasında düzeltmenin', 'Canlı yayınlanan doğa kameralarındaki sinyal kopmasını telafi etmenin'], 'Doğa belgesellerinde süreklilik ve duygusal bağ kurmak amacıyla farklı bireylere ait planların tek bir hayvanın hikayesi gibi kurgulanması yaygın ama tartışmalı bir dramatik inşadır.'),
  ('Bir belgesel öznesinin kamera karşısında sarhoşken, ağır ilaç etkisi altındayken veya akut şok geçirirken imzaladığı yayın izin belgesi (release form) etik ve hukuki açıdan neden sorunludur?', 'Sağlıklı muhakeme yetisi bulunmadığından geçerli aydınlatılmış onam şartını taşımadığı için', ['İmzanın mavi tükenmez kalem yerine siyah keçe uçlu kalemle atılmış olması yüzünden', 'Çekim ekibinin o sırada birden fazla kamerayla farklı açılardan kayıt yapması nedeniyle', 'Formun tek sayfa yerine arkalı önlü iki sayfa halinde basılmış olmasından ötürü'], 'Aydınlatılmış onamın geçerli olabilmesi için kişinin sonuçları kavrayabilecek zihinsel yeterlilikte olması ve baskı ya da bilinç bulanıklığı altında bulunmaması şarttır.'),
  ('"Karanlık Ay Operasyonu" gibi sahte belgesellerin filmin sonunda kendi kurmacalarını açıkça ifşa etmelerinin belgesel kuramı açısından pedagojik işlevi nedir?', 'Arşiv, uzman tanıklığı ve otoriter dış sesin izleyiciyi nasıl kolayca yanıltabileceğini göstermek', ['Belgesel yönetmenlerinin kurmaca aksiyon filmlerine geçiş yapmasını hızlandırmak', 'Televizyon kanallarının gece kuşağındaki yayın boşluklarını düşük bütçeyle doldurmak', 'Tarihsel arşivlerin halka kapatılarak yalnızca devlet kurumlarınca izlenmesini savunmak'], 'Bu tür dönüşlü sahte belgeseller, izleyicinin "belgeselse kesin doğrudur" ön kabulünü sarsarak görüntü ve kurgu manipülasyonlarına karşı eleştirel farkındalık kazandırır.'),
  ('Sacha Baron Cohen\'in "Borat" filminde kurmaca bir Kazak gazeteci kimliğine bürünerek gerçek Amerikan vatandaşlarıyla yaptığı habersiz karşılaşmalar hangi iki türün kesişiminde yer alır?', 'Sahte belgesel (mockumentary) ve kışkırtıcı gizli-gerçeklik komedisi', ['Gözlemsel doğa belgeseli ve şiirsel avangart sinema', 'Tarihsel doküdrama ve derleme arşiv sineması', 'Biyografik konuşan kafa belgeseli ve animasyon'], 'Kurmaca bir karakterin gerçek dünyadaki habersiz insanlarla etkileşime girerek toplumsal önyargıları ifşa etmesi sahte belgesel ile gerçeklik (reality) müdahalesini birleştirir.'),
  ('Belgesel sinemada "asimetrik güç ilişkisi" kavramı, yönetmen ile özne arasındaki hangi temel eşitsizliğe dikkat çeker?', 'Kamera, kurgu ve bağlamı belirleme gücünün yönetmenin elinde toplanmasına', ['Öznenin her zaman yönetmenden daha yüksek maddi gelire sahip olmasına', 'Sinema salonlarındaki koltuk sayısının yapımcı tarafından belirlenmesine', 'Kamera ağırlığının ses kayıt cihazından daha fazla olmasına'], 'Özne kendi hayatını ve görüntüsünü ortaya koyarken, binlerce dakikalık kayıttan hangi 90 dakikanın nasıl bir müzik ve bağlamla sunulacağına yönetmenin karar vermesi yapısal bir güç eşitsizliğidir.'),
  ('Modern büyük bütçeli doğa belgesellerinin son 10 dakikasında "Kamera Arkası" veya "Nasıl Çekildi?" bölümlerine yer verilmesinin kurmaca-gerçeklik ilişkisi açısından işlevi nedir?', 'Görüntülerin hangi teknolojik çaba ve saha koşullarında kaydedildiğini şeffafça paylaşmak', ['Belgeseldeki bütün hayvanların aslında evcil olduğunu izleyiciye itiraf etmek', 'Ana belgeselde süreyi dolduramayan hatalı ve bulanık çekimleri değerlendirmek', 'Kameramanların bir sonraki kurmaca sinema filmleri için oyunculuk seçmesi yapmak'], 'Yapım sürecini, bekleyiş aylarını ve kullanılan kamera düzeneklerini göstermek hem emeği görünür kılar hem de sahnelerin nasıl yakalandığına dair izleyici güvenini pekiştirir.'),
  ('Gerçek suç (true crime) belgesellerinde henüz mahkemesi sonuçlanmamış bir olayda belirli bir kişinin gerilim müziği ve seçmeci kurguyla kesin suçlu gibi gösterilmesi hangi etik ve hukuki ilkeyi zedeler?', 'Masumiyet karinesi ve adil yargılanma hakkını', ['Telif haklarının uluslararası korunması ilkesini', 'Arşiv filmlerinin soğuk hava deposunda saklanması kuralını', 'Görüntü yönetmeninin sanatsal çerçeveleme özgürlüğünü'], 'Yargı süreci devam eden davalarda manipülatif kurgu ve dramatik müzikle kamuoyunda yargısız infaz yaratmak masumiyet karinesini ağır biçimde ihlal eder.'),
  ('Belgesel kuramında 1920\'lerin "Berlin: Büyük Bir Şehrin Senfonisi" ve "Yağmur" gibi filmlerinde görülen, açıklayıcı bilgi ve karakter öyküsü yerine görsel ritim, ton ve çağrışımlara odaklanan Bill Nichols kipi hangisidir?', 'Şiirsel kip (poetic mode)', ['Açıklayıcı kip (expository mode)', 'Katılımcı kip (participatory mode)', 'Gözlemsel kip (observational mode)'], 'Şiirsel kip, zamansal ve mekansal süreklilik kurmak veya bilgi vermek yerine görüntülerin ritmik montajıyla estetik bir izlenim yaratır.'),
  ('Bir tarih belgeselinde 4:3 ekran oranında çekilmiş eski televizyon arşivlerini 16:9 geniş ekran bir yapıma yerleştirirken görüntüyü enine sündürüp deforme etmemek için kenarlarda oluşan boşluğu doldurmada sıkça hangi teknik uygulanır?', 'Pillarbox', ['Anamorfik sıkıştırma ile yüzleri yatay eksende iki kat genişletme', 'Görüntünün üst ve alt yarısını tamamen keserek yalnızca gözleri bırakma', 'Eski kaydı kare kare elle yeniden yağlıboya tabloya dönüştürme'], '4:3 arşiv görüntüsünün orijinal en-boy oranını bozmamak için sağ ve sol kenarlarda siyah boşluk bırakılır ya da aynı görüntünün flu kopyası fon olarak kullanılır.'),
  ('2021 yapımı "Kaçış" (Flee) belgeselinde Afganistan\'dan Danimarka\'ya sığınan eşcinsel bir mültecinin gerçek hayat hikayesini anlatırken animasyon tekniğinin seçilmesinin birincil etik gerekçesi nedir?', 'Anlatıcının gerçek kimliğini ve güvenliğini korurken travmatik geçmişi görünür kılmak', ['Danimarka yasalarının gerçek kameralarla belgesel çekimini tamamen yasaklamış olması', 'Çocuk izleyiciler için neşeli bir çizgi film serisi başlatmak istenmesi', 'Gerçek röportaj ses kayıtlarının yangında tamamen yok olmuş olması'], 'Yönetmen Jonas Poher Rasmussen, hem kahramanı Amin\'in kimliğini gizleyip güvenliğini sağlamak hem de kamerasız anıları canlandırmak için animasyonu etik bir kalkan olarak kullanmıştır.'),
  ('Bir belgeselcinin, kendisiyle konuşmayı reddeden bir kişinin evinin önünden teleobjektifle pencereden içeriyi çekerek yayınlaması hangi temel ilkenin doğrudan ihlalidir?', 'Konut dokunulmazlığı ve özel hayatın gizliliği', ['Göz çizgisi eşleşmesi (eyeline match) kuralı', 'Üçte bir kadrajlama (rule of thirds) estetiği', 'Doğal ışıkla çekim yapma manifestosu'], 'Özel mülk sınırları içindeki yaşamı rıza olmaksızın uzaktan merceklerle kaydetmek hem hukuki hem de etik açıdan ağır bir mahremiyet ihlalidir.'),
  ('Frederick Wiseman tarzı kurumsal gözlemsel belgesellerde hiçbir dış ses (voice-over) veya uzman görüşü yer almamasına rağmen yönetmenin "tarafsız bir ayna" sayılamayacağının en güçlü kanıtı nedir?', 'Yüzlerce saatlik çekimden hangi anların hangi sırayla birleştirileceğine kurguda karar vermesi', ['Çekim sırasında bütün kurum çalışanlarına ezberlemeleri için yazılı senaryo dağıtması', 'Görüntülerin tamamını stüdyoda kurulan yapay hastane dekorlarında çekmiş olması', 'Kameranın önüne renkli jelatin filtreler takarak mekanı olduğundan karanlık göstermesi'], 'Dış ses kullanılmasa bile kamera açısı seçimi ve kurgudaki ayıklama-sıralama işlemi başlı başına ideolojik ve dramatik bir yorumlama (argüman kurma) sürecidir.'),
  ('Bir doğa belgeseli ekibi kutuplarda eksi 40 derecede time-lapse çekimi yaparken kamera bataryasının hızla tükenmesini ve merceğin buğulanmasını önlemek için hangi saha önlemini alır?', 'Yalıtımlı dış güç kaynağı ve mercek ısıtıcı bant kullanmak', ['Kamerayı her beş dakikada bir sıcak su dolu kovaya batırmak', 'Merceğin ön camını sökerek doğrudan açık sensörle kayıt almak', 'Time-lapse aralığını saniyede 120 kareye çıkararak kamerayı ısıtmak'], 'Aşırı soğuk doğa koşullarında lityum piller hızla güç kaybettiği ve sıcaklık farkı yoğuşma yaptığı için harici yalıtımlı bataryalar ve düşük voltajlı lens ısıtıcıları kullanılır.'),
  ('1970\'lerde Maysles Kardeşler\'in eski sosyete mensubu anne ve kızın yıkık dökük malikanelerindeki tuhaf ve yalıtılmış yaşamlarını çektiği "Grey Gardens" (1975) belgeseli hangi etik tartışmayla anılır?', 'Psikolojik kırılganlığı olan öznelerin teşhir edilmesi ile samimi öz-ifade alanı açılması arasındaki ince çizgi', ['Malikanenin bahçesindeki yabani hayvanların yapım ekibince kafeslere kapatılması', 'Anne ve kızın aslında profesyonel Broadway oyuncuları olduğunun yıllar sonra anlaşılması', 'Belgeselde kullanılan bütün eski fotoğrafların sahte olarak çizilmiş olması'], 'Grey Gardens\'ta öznelerin kameraya büyük bir arzuyla performans sergilemesi ama aynı zamanda sağlıksız yaşam koşullarının sergilenmesi rıza ve teşhir tartışmalarının klasik örneğidir.'),
  ('Tarih belgesellerinde eski sessiz arşiv filmlerine sonradan top patlaması, at kişnemesi, kalabalık uğultusu ve ayak sesleri eklenmesi izleyici algısını nasıl etkiler?', 'Tarihsel kayda duyusal gerçekçilik ve şimdiki zaman canlılığı katarken belgenin sessiz doğasını değiştirir', ['Arşiv görüntüsünün hangi kameraman tarafından çekildiğini kesin olarak kanıtlar', 'Siyah-beyaz görüntünün insan gözü tarafından renkli olarak algılanmasını sağlar', 'Filmin telif süresini otomatik olarak yüz yıl daha uzatır'], 'Sessiz arşivlere ses tasarımı eklemek izleyiciyi sahnenin içine çeker; ancak bu seslerin olay anına ait gerçek kayıtlar değil sonradan üretilmiş efektler olduğu unutulmamalıdır.'),
  ('2010 yapımı "Catfish" belgeselinin ardından popülerleşen, bir kişinin internette sahte kimlik ve fotoğraflarla kurmaca bir kişilik yaratarak duygusal ilişki kurmasını belgeleyen anlatılarda en çok hangi şüphe tartışılmıştır?', 'Belgesel ekibinin gerçeği önceden bilip şaşkınlık anlarını kamera için yeniden sahnelemiş olma ihtimali', ['İnternet ekran görüntülerinin siyah-beyaz kameralarla kaydedilememesi sorunu', 'Filmde geçen şehirlerin aslında haritada hiç var olmaması', 'Müzik telifleri nedeniyle bütün diyalogların sessize alınmış olması'], 'Catfish filminde olayların gelişimindeki kusursuz dramatik zamanlama, yapımcıların gerçeği ne zaman öğrendiği ve ne kadarını kurguladığı yönünde ciddi otantiklik tartışmaları yaratmıştır.'),
  ('Bir belgesel yönetmeni travmatik bir şiddet olayından sağ kurtulan kişiyle "konuşan kafa" röportajı yaparken yeniden travmatizasyonu (re-traumatization) önlemek için nasıl bir yaklaşım sergilemelidir?', 'Özneye kontrol alanı tanımak, istediğinde kaydı durdurabileceğini belirtmek ve duygusal sömürüden kaçınmak', ['Özneyi ağlatıp dramatik görüntü yakalamak için habersizce saldırganın fotoğraflarını göstermek', 'Röportaj odasının kapısını kilitleyerek tüm sorular bitene kadar mola verilmesini engellemek', 'Öznenin anlattığı her cümleye şüpheyle yaklaşıp sert çapraz sorgu teknikleri uygulamak'], 'Travma duyarlı belgesel etiğinde gözyaşı yakalamak uğruna özneyi zorlamak kabul edilemez; güvenli ortam, mola hakkı ve psikolojik sınırların korunması esastır.'),
  ('Bir televizyon doküdramasında gerçek hayatta hala yaşayan yardımcı karakterlerin kişilik hakları davası açmasını önlemek için senaristlerin birden fazla gerçek kişiyi tek bir hayali isim altında birleştirmesine ne denir?', 'Bileşik (kompozit) karakter yaratımı', ['Doğrudan arşiv aktarım tekniği', 'Aydınlatılmış onam iptali', 'Zaman atlamalı kurgu birleşimi'], 'Doküdramalarda hem dramatik akışı yoğunlaştırmak hem de yaşayan üçüncü kişilerin mahremiyet ve iftira davası riskini azaltmak için kompozit karakterler oluşturulur; ancak bu durum tarihsel birebirliği azaltır.'),
  ('2003 yapımı doküdrama-belgesel "Touching the Void" (Boşluğa Dokunmak), Peru Andları\'nda kaza geçiren iki dağcının hikayesini anlatırken canlandırma ile konuşan kafayı nasıl dengeler?', 'Gerçek dağcıların sade kamera önü tanıklıklarını, oyuncuların dağda çekilen gerilimli canlandırmalarıyla kurgulayarak', ['Dağcıları stüdyoda yeşil perde önünde iplere asıp komedi skeçleri oynatarak', 'Kaza anına ait gerçek güvenlik kamerası kayıtlarını hiç kesmeden yayınlayarak', 'Hiçbir insan sesi kullanmadan yalnızca dağ rüzgarının sesini dinleterek'], 'Kevin Macdonald\'ın yönettiği film, gerçek dağcıların dingin yüzleşmelerini konuşan kafa formatında verirken fiziksel hayatta kalma mücadelesini yüksek prodüksiyonlu canlandırmalarla bütünleştirmiştir.'),
  ('Bir belgeselde "arşiv görüntüsünün fetişleştirilmesi" eleştirisi hangi durumu anlatmak için kullanılır?', 'Görüntü kalitesi düşük veya sarsıntılı her eski kaydın bağlamı sorgulanmadan mutlak hakikat sanılması', ['Arşiv filmlerinin müzelerde nem ve sıcaklık kontrolü altında özenle korunması', 'Belgesel yönetmenlerinin telif hakları için bütçeden özel bir pay ayırması', 'Eski selüloit filmlerin yangın tehlikesine karşı dijital ortama aktarılması'], 'Görüntünün grenli, siyah-beyaz veya amatör olması onu kendiliğinden doğru kılmaz; kimin, ne amaçla çektiği ve neyi kadraj dışında bıraktığı sorgulanmadan kanıt sayılması yanıltıcıdır.'),
  ('Bir doğa belgeselcisi çiçek açan bir orkidenin etrafında tozaklayıcı arının uçuşunu çekerken hem arının kanat hareketini net dondurmak hem de çiçeğin zaman içindeki açılışını göstermek isterse çekim planını nasıl kurmalıdır?', 'Çiçeğin açılışını uzun aralıklı time-lapse ile, arının gelişini ise yüksek kare hızlı ağır çekimle ayrı ayrı çekmek', ['Tek bir kamerayla saniyede 1 kare çekerek hem çiçeği hem uçan arıyı ağır çekimde yakalamak', 'Kameranın mercek kapağını kapatarak yalnızca ses kaydı üzerinden görsel efekt üretmek', 'Saniyede 1000 kareyle aralıksız 15 gün boyunca hiç durmadan kayıt yaparak hafıza kartını doldurmak'], 'Çok yavaş süreçler (çiçek açması) düşük kare aralıklı time-lapse gerektirirken, çok hızlı hareketler (arı kanadı) saniyede yüzlerce karelik high-speed çekim gerektirir; ikisi kurguda birleştirilir.'),
  ('Christopher Guest\'in yönettiği "Best in Show" (2000) ve "Waiting for Guffman" (1996) gibi sahte belgesellerde oyuncuların diyaloglarının doğal ve gerçek belgesel röportajı gibi durması için hangi oyunculuk yöntemi uygulanmıştır?', 'Detaylı karakter geçmişi yazılıp sahnelerin ve röportajların doğaçlama (improvisation) oynanması', ['Sokaktan geçen habersiz insanların gizli kamerayla çekilip sonradan dublaj yapılması', 'Oyuncuların kamera arkasındaki dev kartonlardan kelimesi kelimesine haber metni okuması', 'Gerçek köpek yarışması katılımcılarının hipnoz altında kamera karşısına çıkarılması'], 'Christopher Guest ekolü sahte belgesellerde olay örgüsü bellidir ancak oyuncular sahneleri ve konuşan kafa röportajlarını doğaçlayarak belgesel doğallığını yakalar.'),
  ('Bir şirketin veya siyasi partinin tüm bütçesini karşıladığı, konu seçiminden son kurguya kadar onay yetkisini elinde tuttuğu yapımların "bağımsız belgesel" olarak sunulması hangi etik sorunu yaratır?', 'Çıkar çatışmasının gizlenerek kurumsal tanıtım veya propagandanın gazetecilik gibi pazarlanması', ['Sponsor logonun jenerikte küçük puntolarla yazılması nedeniyle okunamaması', 'Kurumsal binalarda floresan ışık kullanıldığı için renk dengesinin yeşile kayması', 'Şirket yöneticilerinin kamera karşısında kravat takma zorunluluğu getirmesi'], 'Finansman kaynağının filmin öznesiyle doğrudan çıkar ilişkisi içinde olması ve bunun izleyiciden gizlenmesi editoryal bağımsızlığı ortadan kaldırır.'),
  ('2013 yapımı "Blackfish" belgeseli, deniz parklarında esaret altında tutulan katil balina Tilikum\'un hikayesini eski eğitmenlerin konuşan kafa tanıklıkları ve arşiv kayıtlarıyla anlatarak hangi toplumsal etkiyi yaratmıştır?', 'Esaret altındaki deniz memelileri gösterilerine yönelik küresel kamuoyu tepkisi ve yasal-kurumsal kısıtlamalar', ['Su parklarına giden ziyaretçi sayısının tüm dünyada on katına çıkması', 'Okyanuslardaki bütün katil balinaların yakalanarak akvaryumlara taşınması', 'Doğa belgesellerinde su altı kamerası kullanımının tamamen yasaklanması'], 'Blackfish, arşiv görüntüleri ve içeriden tanıklıkları birleştiren araştırmacı belgeselciliğin hayvan hakları ve şirket politikaları üzerinde nasıl somut değişim yaratabileceğinin simgesi olmuştur.'),
  ('Sosyal medyadan veya video paylaşım sitelerinden indirilen vatandaş gazeteciliği (amatör cep telefonu) görüntülerini bir tarih veya güncel olay belgeselinde kullanmadan önce yapımcının ilk yapması gereken etik doğrulama nedir?', 'Görüntünün çekildiği yer, tarih ve kaynağı teyit ederek başka bir olaydan alınmadığını doğrulamak', ['Görüntünün üzerine yapay kamera sarsıntısı ve siyah-beyaz çizik efekti eklemek', 'Videodaki bütün orijinal sesleri silip yerine telifsiz neşeli müzik yerleştirmek', 'Kaydı çeken kişiden habersiz görüntüyü kendi kameramanı çekmiş gibi jeneriğe yazmak'], 'Dijital çağda eski veya farklı coğrafyalara ait videolar sıkça yeni olaylarmış gibi dolaşıma sokulduğu için açık kaynak doğrulaması (coğrafi konum, hava durumu, meta veri kontrolü) zorunludur.'),
  ('Doğa belgeselciliğinde kutup ayısı veya kaplan gibi tehlikeli yırtıcıların yaşam alanına gizlenmiş, hareket ve ısı sensörüyle tetiklenerek ekip yokken kayıt yapan kameralara ne ad verilir?', 'Fotokapan', ['Steadicam yelek sistemi', 'Stüdyo omuz kamerası', 'Vinç (jimmy jib) kamerası'], 'İnsan kokusu ve varlığından çekinen nadir ya da tehlikeli yabani hayvanları doğal davranışları içinde rahatsız etmeden belgelemek için sensörlü fotokapanlar kullanılır.'),
  ('"Grizzly Man" belgeselinin büyük bölümü Timothy Treadwell\'in hayattayken kendi kamerasıyla çektiği yüzlerce saatlik görüntüden oluşur; Herzog bu malzemeyi nasıl dönüştürmüştür?', 'Treadwell\'in doğayı romantize eden kayıtlarını kendi kuşkucu dış sesi ve tanık röportajlarıyla yeniden çerçeveleyerek', ['Görüntülerdeki bütün ayıları bilgisayar efektiyle silip yerine evcil köpekler yerleştirerek', 'Treadwell\'in çektiği görüntüleri hiçbir kurgu yapmadan kronolojik sırayla yayınlayarak', 'Doğa görüntülerini hızlandırıp komedi müziği eşliğinde bir sahte belgesele çevirerek'], 'Herzog, Treadwell\'in doğayı dostane ve insansı gören kayıtlarını alıp doğanın kayıtsız ve vahşi doğasını vurgulayan kendi felsefi yorumuyla karşı karşıya getirmiştir.'),
  ('Bir doküdrama yapımcısı, yakın tarihte yaşanmış büyük bir maden kazasını filmleştirirken hem gerçeğe sadık kalmak hem de hayatını kaybeden madencilerin ailelerini incitmemek için ön hazırlıkta nasıl hareket etmelidir?', 'Ailelerle ve sağ kurtulanlarla görüşerek duyarlılıkları gözetmek, resmi tutanakları incelemek ve uydurma sansasyondan kaçınmak', ['Olayla ilgili hiçbir araştırma yapmadan kazayı uzaylı saldırısı olarak yeniden yazmak', 'Ailelerin itirazlarına rağmen cenaze törenlerini habersizce oyuncularla mezarlıkta yeniden çekmek', 'Kazanın sorumlularından sponsorluk alarak suçu hayatını kaybeden işçilere yüklemek'], 'Yakın tarihli toplumsal travmaları konu alan doküdramalarda olgusal titizlik kadar yas tutan ailelerin onurunu ve duygusal sınırlarını gözetmek de birincil sorumluluktur.'),
  ('Yeni Zelanda yapımı "What We Do in the Shadows" (Aylak Vampirler, 2014), aynı evi paylaşan yüzyıllık vampirlerin bulaşık sırası ve kira kavgalarını hangi sinemasal dille komediye dönüştürmüştür?', 'Gözlemsel ev-içi belgesel ve konuşan kafa röportajı formatını kullanan sahte belgesel (mockumentary) diliyle', ['Siyah-beyaz sessiz dışavurumcu Alman korku sineması ara yazılarıyla', 'Yüksek bütçeli bilimsel doğa belgeseli ve makro çekim teknikleriyle', 'Resmi mahkeme tutanaklarına dayanan ciddi tarihsel doküdrama üslubuyla'], 'Taika Waititi ve Jemaine Clement, doğaüstü gotik vampir mitolojisini sıradan bir televizyon belgeseli ekibinin ev ziyareti formatına sokarak başarılı bir mockumentary komedisi yaratmıştır.'),
  ('Bir doğa belgeselinde stüdyo teraryumunda çekilmiş bir akrebin görüntüsü ile çölde çekilmiş geniş plan kumul görüntüsünün kurguda ardı ardına bağlanarak akrebin o çölde yürüdüğü izleniminin verilmesi sinema kuramındaki hangi ilkeye dayanır?', 'Kuleşov etkisi ve yaratıcı coğrafya kurgusuna', ['Doğrudan sinemanın kesintisiz tek plan kuralına', 'Aydınlatılmış onam ve özne hakları bildirgesine', 'Zaman atlamalı astro-fotoğrafçılık tekniğine'], 'Lev Kuleşov\'un kanıtladığı gibi izleyici ardı ardına gelen iki ayrı mekan çekimini zihninde tek bir bütünleşik mekan (yaratıcı coğrafya) olarak birleştirir; doğa belgesellerinde bu teknik sıkça kullanılır ancak şeffaflık tartışması doğurur.'),
  ('Bir belgeselde "konuşan kafa"nın bakış boşluğu bilerek kapatılıp öznenin kadrajın baktığı kenarına sıkıştırılması (short-siding) yönetmen tarafından bilinçli tercih edildiğinde hangi psikolojik etkiyi verir?', 'Kapana kısılmışlık, yabancılaşma, gerilim veya öznenin içsel huzursuzluğu', ['Öznenin çok geniş bir arazide doğa yürüyüşü yaptığı hissi', 'Röportajın neşeli bir sabah programında canlı yayınlandığı izlenimi', 'Kameramanın üçayak kullanmayı bilmediğine dair teknik yetersizlik'], 'Standart bakış boşluğu kuralını (Mr. Robot veya bazı suç/travma belgesellerinde olduğu gibi) bilinçli yıkmak, öznenin psikolojik sıkışmışlığını görselleştiren güçlü bir estetik tercihtir.'),
  ('Gökyüzündeki Samanyolu kuşağının gece boyunca dönüşünü time-lapse tekniğiyle kaydetmek isteyen bir doğa görüntü yönetmeni pozlama ayarlarını nasıl yapılandırmalıdır?', 'Geniş diyafram açıklığı, yüksek ISO ve her kare için 15-25 saniye civarı uzun pozlama süresi seçerek', ['Diyaframı tamamen kısıp saniyede 1/4000 enstantane hızıyla anlık karanlık kareler çekerek', 'Kamera flaşını her pozlamada patlatarak gökyüzündeki yıldızları aydınlatmaya çalışarak', 'Yalnızca öğle saatlerinde güneş filtresi takarak yıldızların görünmesini bekleyerek'], 'Gece gökyüzü time-lapse (astro-timelapse) çekimlerinde sönük yıldız ışığını toplayabilmek için açık diyaframlı geniş açı lensler ve yıldız izi oluşmayacak sınırda uzun pozlama süreleri kullanılır.'),
  ('İspanyol yönetmen Luis Buñuel\'den yıllar sonra yine İspanya\'da, inşaat halindeki bir binanın yerine yapılan apartmanın sakinleriyle eski mahalle kültürünü ve hafızayı kayda alan José Luis Guerín\'in 2001 yapımı gözlemsel-düşünümsel belgeseli hangisidir?', 'Yapım Aşamasında (En construcción / Work in Progress)', ['Arı Kovanının Ruhu (The Spirit of the Beehive)', 'Pan\'ın Labirenti (Pan\'s Labyrinth)', 'Annem Hakkında Her Şey (All About My Mother)'], 'José Luis Guerín, Barselona\'nın dönüşen El Raval mahallesindeki bir inşaat alanını yıllarca gözlemleyerek kentsel dönüşümü ve zamanın akışını şiirsel-gözlemsel bir belgesele dönüştürmüştür.'),
  ('Doğa belgesellerinde hızlandırılmış çekim (time-lapse) ile bitkilerin güneşe yönelmesi, sarmaşıkların diğer bitkilere dolanması ve mantarların spor saçması gösterildiğinde izleyicinin doğa algısında hangi kırılma yaşanır?', 'Durağan ve cansız bir dekor gibi algılanan bitki örtüsünün aktif, rekabetçi ve hareketli birer canlı olarak kavranması', ['Bitkilerin aslında hayvanlardan daha hızlı koşabildiğine dair yanlış bir bilimsel inanç oluşması', 'Orman ekosisteminin insan müdahalesi olmadan yaşayamayacağının kanıtlanması', 'Fotoğraf makinelerinin doğadaki oksijen oranını artırdığının anlaşılması'], 'İnsan algısının zaman ölçeğiyle örtüşmeyen yavaş biyolojik süreçlerin time-lapse ile hızlandırılması, bitkiler aleminin dinamik davranışlarını görünür kılar.'),
  ('Netflix\'in "The Crown" veya HBO\'nun "Chernobyl" dizisi gibi yüksek bütçeli tarihsel doküdrama yapımları yayınlandığında tarihçilerin ve gerçek tanıkların sıkça dile getirdiği "kurmaca ikamesi" kaygısı nedir?', 'Milyonlarca izleyicinin dramatik amaçla kurgulanan sahneleri ve değiştirilen karakterleri birebir tarihsel gerçek olarak hafızasına kaydetmesi', ['Dizilerde kullanılan dönem kostümlerinin müzelerdeki orijinallerinden daha dayanıklı kumaşla dikilmesi', 'Oyuncuların tarihsel kişiliklere fiziksel olarak hiç benzememesi nedeniyle kimsenin diziyi izlememesi', 'Belgesel kanallarının bu dizilerden sonra tamamen kapanarak yayına son vermesi'], 'Yüksek prodüksiyon kalitesi ve tarihsel detaylardaki görsel inandırıcılık, izleyicinin senaryo icabı uydurulmuş diyalog ve olayları da mutlak tarih sanmasına yol açabilmektedir.'),
  ('Bir belgesel yapımcısı kamu malı (public domain) sayılan çok eski bir tarihsel olaya ait arşiv görüntüsünü özel bir arşiv şirketinden yüksek çözünürlüklü tarama olarak temin ettiğinde neden yine de lisans ücreti ödemek zorunda kalabilir?', 'Tarihsel olay anonimleşse bile fiziksel kopyanın korunması, restorasyonu ve dijital erişim hizmeti üzerinde arşiv kurumunun sözleşmesel hakları bulunabileceği için', ['Kamu malı olan bütün görüntülerin her yıl yeniden çekilmesi yasal zorunluluk olduğu için', 'Siyah-beyaz görüntülerin renkli televizyonlarda yayınlanması özel vergiye tabi olduğu için', 'Görüntüde yer alan yüz yıl önceki kalabalığın her bir ferdinden yeni imza alınması gerektiği için'], 'Belgesel yapımında kamu malı ile arşiv erişim/master kopya ücreti sıkça karıştırılır; arşivin fiziksel muhafaza ve dijital tarama emeği ticari lisanslamaya konu olabilir.'),
  ('Bir belgeselde "konuşan kafa" röportajının hemen öncesinde ve sonrasında, yönetmenin "Kayıt başladı" dediği anın, öznenin koltuğunda kıpırdanmasının ve mikrofon düzeltilmesinin kesilmeyip filmde bırakılması hangi estetik mesajı verir?', 'Röportajın kendiliğinden gelişen doğal bir an değil, kurulan bir sinemasal karşılaşma olduğunu şeffafça hatırlatır', ['Kurgucunun filmin teslim tarihine yetişemediği için kaba kurguyu yanlışlıkla yayınladığını gösterir', 'Mikrofon markasının izleyiciler tarafından görülüp satın alınması için gizli reklam yapıldığını kanıtlar', 'Öznenin birazdan söyleyeceği bütün cümlelerin tamamen yalan olduğunu önceden ilan eder'], 'Çekim hazırlığını ve teknik çerçeveyi kadrajda bırakmak (dönüşlü kip), izleyicinin belgeseli "üretilmiş bir temsil" olarak bilinçli gözle izlemesini sağlar.'),
  ('1922 yapımı İsveç-Danimarka ortak yapımı "Häxan: Çağlar Boyu Cadılık", Orta Çağ\'daki cadı avlarını ve engizisyon işkencelerini çizimler, maketler ve oyuncularla canlandırırken dönemine göre hangi türün erken habercisi olmuştur?', 'Tarihsel-kültürel deneme belgeseli ile korku doküdramasının melez öncüsü', ['Senkron sesli taşınabilir el kamerasıyla çekilen doğrudan sinemanın', 'Yalnızca hayvan davranışlarını inceleyen su altı doğa belgeselinin', 'Televizyon durum komedisi tarzındaki modern sahte belgeselin'], 'Benjamin Christensen\'in yönettiği Häxan, tarihsel inceleme bölümleri ile son derece çarpıcı dramatik canlandırmaları birleştirerek belgesel ve doküdrama tarihinin en özgün erken örneklerinden biri olmuştur.'),
  ('Bir belgeselde farklı günlerde yapılan iki ayrı röportajın tek bir gün yapılmış gibi kurgulanabilmesi için özneye ikinci gün de aynı kıyafetin giydirilmesi kurmaca-gerçeklik bağlamında neyi gösterir?', 'Belgesel kurgusunun da görsel süreklilik (devamlılık) kurallarıyla inşa edildiğini', ['Öznenin dolabında başka hiçbir kıyafetinin bulunmadığını', 'Aynı kıyafet giyilmezse kameranın teknik olarak odaklama yapamadığını', 'Yönetmenin ikinci gün yanlışlıkla ilk günün kasetini silmiş olduğunu'], 'Belgeseller gerçek kişileri konu alsa da kurgudaki anlatım akıcılığını sağlamak adına sinemanın görsel devamlılık (continuity) tekniklerinden yararlanır.'),
  ('Bir doğa belgeseli kurgucusu, 5 saatlik sabit kamera kaydında yuvadaki kuşun yalnızca 3 kez besleme yaptığını görürse, izleyiciyi sıkmadan gerçeği çarpıtmamak için nasıl bir anlatım kurmalıdır?', 'Besleme anlarını seçip dış ses veya görsel geçişlerle aradan saatler geçtiğini doğru biçimde belirterek kurgulamak', ['Aynı besleme planını aynalayarak art arda 20 kez yapıştırıp kuşun dakikada bir beslendiğini söylemek', 'Yuvanın yanına stüdyoda çekilmiş farklı bir kıtaya ait papağan görüntüleri eklemek', 'Hiçbir kesme yapmadan 5 saatlik boş yuva görüntüsünü televizyonun ana haber kuşağında yayınlamak'], 'Zaman sıkıştırması belgesel kurgusunun doğal parçasıdır; önemli olan eliptik geçişlerle zamanın akışını doğru ifade etmek ve biyolojik sıklığı yanlış tanıtmamaktır.'),
  ('Kurmaca bir olay örgüsünü gerçek bir belgesel gibi sunan Orson Welles\'in 1938 tarihli "Dünyalar Savaşı" radyo yayını ile modern televizyon sahte belgesellerinin ortak yapısal stratejisi nedir?', 'Kitle iletişim araçlarının güvenilirlik kodlarını (canlı bağlantı, uzman görüşü, teknik kesinti) taklit ederek gerçeklik yanılsaması üretmek', ['Yalnızca klasik tiyatro sahnesinde perde açılıp kapanarak seyirciye masal anlatmak', 'Yayının her dakikasında "bu tamamen uydurmadır" uyarısını yüksek sesle tekrarlamak', 'Hiçbir ses efekti veya dış mekan atmosferi kullanmadan akademik makale okumak'], 'İzleyici veya dinleyici, alışkın olduğu resmi haber/belgesel biçimsel kodlarını (muhabir sesi, uzman profesör, saha gürültüsü) duyduğunda içeriğin doğruluğunu sorgulamadan kabul etme eğilimi gösterir.'),
  ('Godfrey Reggio\'nun yönettiği, Philip Glass\'ın hipnotik müziği eşliğinde doğanın dinginliği ile modern endüstriyel kent yaşamının çılgın hızını time-lapse ve ağır çekimlerle karşılaştıran 1982 yapımı sözsüz belgesel klasiği hangisidir?', 'Koyaanisqatsi', ['Nanook of the North', 'The Thin Blue Line', 'Grey Gardens'], 'Hopi dilinde "dengesiz yaşam" anlamına gelen Koyaanisqatsi, tek kelime diyalog veya dış ses kullanmadan time-lapse sinematografisini felsefi ve ekolojik bir eleştiri aracına dönüştürmüştür.'),
  ('Bir belgeselde yapımcının, maddi durumu yetersiz bir hastanın ameliyat masrafını karşılayıp karşılığında ameliyat sürecini sadece kendi kameralarına açmasını şart koşması hangi etik açmazı doğurur?', 'Hayati çaresizliğin istismar edilerek rızanın zorunluluk altında alınması', ['Ameliyathane ışıklarının kamera sensöründe mavi leke bırakması', 'Doktorların tıbbi terimleri Latince telaffuz etmesi nedeniyle altyazı gerekmesi', 'Hastane koridorlarının geniş açılı çekime uygun olmaması'], 'Kişinin yaşamsal bir tedaviye ulaşabilmesinin tek yolu kameraya izin vermek haline getirildiğinde özgür iradeye dayalı aydınlatılmış onamdan söz edilemez; bu durum kırılganlığın sömürüsüdür.'),
  ('Bir doğa belgeselcisi göçmen kuşların sulak alandaki konaklamasını çekerken kamuflaj çadırı (hide/blind) içinde saatlerce sessiz ve hareketsiz beklemek zorundadır; bu yöntemin hem bilimsel hem sinemasal kazancı nedir?', 'İnsan varlığından kaynaklanan kaçma veya savunma tepkisini ortadan kaldırarak otantik doğal davranışı yakalamak', ['Çadırın içindeki karanlık sayesinde görüntüleri otomatik olarak siyah-beyaza çevirmek', 'Kuşların çadırın içine girerek kamerayı kendi gagalarıyla çalıştırmasını sağlamak', 'Rüzgar sesini on kat artırarak kurguda dramatik fırtına efekti elde etmek'], 'Kamuflaj gizlenme noktaları (blinds), gözlemcinin ekosisteme etkisini en aza indirerek hayvanların beslenme, kur yapma ve dinlenme davranışlarını doğal akışında kaydetmeyi sağlar.'),
  ('Arşiv görüntülerinin kullanımında "temsili genelleme" hatası olarak tanımlanan; örneğin 1930\'ların başında çekilmiş bir fabrika görüntüsünün 1940\'ların sonundaki bambaşka bir sanayi grevini anlatırken fon olarak kullanılması neye yol açar?', 'Tarihsel dönemlerin özgül koşullarını düzleştirerek arşivi salt görsel duvar kağıdına indirgemeye', ['İzleyicilerin siyah-beyaz televizyon satın alma oranının hızla yükselmesine', 'Fabrikadaki makinelerin çalışma prensibinin mühendisler tarafından daha iyi anlaşılmasına', 'Belgeselin görüntü kalitesinin 4K çözünürlüğe kendiliğinden yükselmesine'], 'Arşiv görüntülerini tarihsel bağlamına ve tarihine dikkat etmeksizin "nasılsa eski görüntü" diyerek dolgu malzemesi (wallpaper B-roll) yapmak tarihsel titizliği yok eder.'),
];
